/* HSK 5 grammar checklist — grammar points for HSK 2.0 level 5.
   Same shape as data/grammar.js (window.CB_GRAMMAR). Explanations, examples and practice questions are
   original content written for this app. NOT yet reviewed by a human teacher: see data/hsk5/GRAMMAR.md. */
window.CB_HSK5_GRAMMAR = [
  {"id":"h5g01","title":{"zh":"以……为……","vi":"Lấy… làm…","en":"以…为… (take A as B)"},"pattern":"以 + A + 为 + B (为主 / 为例 / 为基础 / 为目标 / 为中心 / 为对象)","explain":{"vi":"Cấu trúc văn viết: lấy A làm B, coi A là B. 为 đọc là wéi. Hay gặp trong các cụm cố định: 以…为主, 以…为例, 以…为基础. Lỗi hay gặp: dùng 把 thay cho 以 (把…为主 là sai) hoặc bỏ mất 为.","en":"A written pattern: take A as B, treat A as B. 为 is read wéi. Common in set phrases: 以…为主, 以…为例, 以…为基础. Common mistake: using 把 instead of 以 (把…为主 is wrong) or dropping 为."},"examples":[{"zh":"我们部门的工作以招聘和培训为主。","py":"Wǒmen bùmén de gōngzuò yǐ zhāopìn hé péixùn wéi zhǔ.","vi":"Công việc của bộ phận chúng tôi chủ yếu là tuyển dụng và đào tạo.","en":"Our department's work is mainly recruitment and training."},{"zh":"公司以去年的销售数据为基础制定计划。","py":"Gōngsī yǐ qùnián de xiāoshòu shùjù wéi jīchǔ zhìdìng jìhuà.","vi":"Công ty lập kế hoạch dựa trên số liệu bán hàng năm ngoái.","en":"The company draws up its plan on the basis of last year's sales data."}],"quiz":[{"q":"这次调查____三十岁以下的员工为对象。","options":["把","被","对","以"],"answer":3,"explain":{"vi":"以…为对象: lấy… làm đối tượng.","en":"以…为对象: take … as the target group."}},{"q":"南方人的主食以米饭____主。","options":["为","是","当","成"],"answer":0,"explain":{"vi":"以…为主: lấy… làm chính.","en":"以…为主: mainly …."}},{"q":"下面我____这家公司为例，说明一下这个问题。","options":["从","以","由","按"],"answer":1,"explain":{"vi":"以…为例: lấy… làm ví dụ.","en":"以…为例: take … as an example."}},{"q":"“以学习为主”的意思是：","options":["因为学习很重要","为了学习","把学习当作最主要的事","只学习主要的内容"],"answer":2,"explain":{"vi":"以A为主 = coi A là việc chính.","en":"以A为主 = treat A as the main thing."}},{"q":"下面哪个句子是正确的？","options":["这家餐厅以海鲜为特色。","这家餐厅为海鲜以特色。","这家餐厅以海鲜特色为。","以这家餐厅海鲜为特色。"],"answer":0,"explain":{"vi":"Trật tự: chủ ngữ + 以 + A + 为 + B.","en":"Order: subject + 以 + A + 为 + B."}}]},
  {"id":"h5g02","title":{"zh":"把……当作 / 看作 / 视为","vi":"Coi… là…","en":"把…当作 / 看作 / 视为 (regard A as B)"},"pattern":"S + 把 + A + 当作 / 当成 / 看作 / 视为 + B | A + 被 + (agent) + 视为 / 看作 + B","explain":{"vi":"Nói cách nhìn nhận, đối xử: coi A là B. 视为 trang trọng nhất. Từ phủ định và trợ động từ đứng trước 把. Lỗi hay gặp: dùng 认为 với 把 (把他认为朋友 là sai, phải nói 把他当作朋友 hoặc 认为他是朋友).","en":"States how someone views or treats something: regard A as B. 视为 is the most formal. Negatives and modals go before 把. Common mistake: using 认为 with 把 (把他认为朋友 is wrong; say 把他当作朋友 or 认为他是朋友)."},"examples":[{"zh":"她把每一次失败都当作学习的机会。","py":"Tā bǎ měi yí cì shībài dōu dàngzuò xuéxí de jīhuì.","vi":"Cô ấy coi mỗi lần thất bại đều là một cơ hội học hỏi.","en":"She treats every failure as a chance to learn."},{"zh":"很多人把他视为这个行业的专家。","py":"Hěn duō rén bǎ tā shìwéi zhège hángyè de zhuānjiā.","vi":"Nhiều người coi anh ấy là chuyên gia trong ngành này.","en":"Many people regard him as an expert in this industry."}],"quiz":[{"q":"我一直____他当作最好的朋友。","options":["被","把","以","对"],"answer":1,"explain":{"vi":"Cấu trúc 把 + A + 当作 + B: coi A là B.","en":"把 + A + 当作 + B: regard A as B."}},{"q":"公司把员工的健康____最重要的事情。","options":["看见","看来","看望","看作"],"answer":3,"explain":{"vi":"把…看作…: coi… là….","en":"把…看作…: regard … as …."}},{"q":"下面哪个句子是正确的？","options":["你把我的话别当成玩笑。","你别把当成我的话玩笑。","你别把我的话当成玩笑。","你别我的话把当成玩笑。"],"answer":2,"explain":{"vi":"别 đứng trước 把; sau 把 là A, rồi 当成 + B.","en":"别 goes before 把; then A, then 当成 + B."}},{"q":"这次比赛被大家____一次难得的锻炼机会。","options":["视为","认为","以为","成为"],"answer":0,"explain":{"vi":"被…视为…: được coi là…; 认为 phải nói 认为是.","en":"被…视为…: be regarded as…; 认为 would need 是."}},{"q":"“他把公司当成自己的家”的意思是：","options":["他住在公司里","他对公司像对家一样有感情","公司是他家开的","他想把公司搬到家里"],"answer":1,"explain":{"vi":"把A当成B: đối xử với A như là B.","en":"把A当成B: treat A as if it were B."}}]},
  {"id":"h5g03","title":{"zh":"被……所…… / 为……所……","vi":"Bị động trang trọng 被…所… / 为…所…","en":"被…所… / 为…所… (formal passive)"},"pattern":"S + 被 / 为 + agent + 所 + V (two-syllable verb)","explain":{"vi":"Câu bị động dùng trong văn viết; 所 đứng ngay trước động từ, 为 đọc là wéi. Động từ thường hai âm tiết và phía sau không cần thêm thành phần khác. Lỗi hay gặp: đặt 所 sai vị trí (所被…感动 là sai) hoặc thêm bổ ngữ dài phía sau động từ.","en":"A passive used in writing; 所 goes right before the verb and 为 is read wéi. The verb is usually two syllables and needs nothing after it. Common mistake: misplacing 所 (所被…感动 is wrong) or adding a long complement after the verb."},"examples":[{"zh":"我被他认真的工作态度所感动。","py":"Wǒ bèi tā rènzhēn de gōngzuò tàidu suǒ gǎndòng.","vi":"Tôi cảm động trước thái độ làm việc nghiêm túc của anh ấy.","en":"I was moved by his conscientious attitude to work."},{"zh":"这种新的管理方式已为大家所接受。","py":"Zhè zhǒng xīn de guǎnlǐ fāngshì yǐ wéi dàjiā suǒ jiēshòu.","vi":"Cách quản lý mới này đã được mọi người chấp nhận.","en":"This new management style has been accepted by everyone."}],"quiz":[{"q":"观众们都被她的表演____吸引。","options":["把","以","所","而"],"answer":2,"explain":{"vi":"被…所 + động từ.","en":"被…所 + verb."}},{"q":"他的做法不____大多数同事所理解。","options":["为","把","以","向"],"answer":0,"explain":{"vi":"为…所 + động từ: bị động trang trọng.","en":"为…所 + verb: formal passive."}},{"q":"下面哪个句子是正确的？","options":["我们不能所被眼前的困难吓倒。","我们不能被眼前的困难吓倒所。","我们被所眼前的困难不能吓倒。","我们不能被眼前的困难所吓倒。"],"answer":3,"explain":{"vi":"所 đứng ngay trước động từ; 不能 đứng trước 被.","en":"所 goes right before the verb; 不能 goes before 被."}},{"q":"“为……所……”多用于：","options":["朋友之间聊天","比较正式的文章","问问题的时候","命令别人的时候"],"answer":1,"explain":{"vi":"Đây là cấu trúc của văn viết trang trọng.","en":"This is a pattern of formal writing."}},{"q":"这位老教授深为学生们所____。","options":["尊敬了他","把他尊敬","尊敬","尊敬得很"],"answer":2,"explain":{"vi":"Sau 所 là động từ hai âm tiết, không thêm thành phần khác.","en":"所 is followed by a bare two-syllable verb."}}]},
  {"id":"h5g04","title":{"zh":"所 + 动词 + 的","vi":"所 + động từ + 的","en":"所 + V + 的 (what is V-ed)"},"pattern":"(S) + 所 + V + 的 (+ N) | 据 + S + 所知","explain":{"vi":"所 đứng trước động từ có tân ngữ để tạo cụm danh từ: \"cái mà… (làm)\". 所 đứng sau chủ ngữ, trước động từ; văn viết dùng nhiều. Lỗi hay gặp: đặt 所 trước chủ ngữ (所我知道的 là sai, phải nói 我所知道的).","en":"所 before a transitive verb builds a noun phrase: \"that which is V-ed\". It goes after the subject and before the verb, mostly in writing. Common mistake: placing 所 before the subject (所我知道的 is wrong; say 我所知道的)."},"examples":[{"zh":"这就是我所了解的全部情况。","py":"Zhè jiù shì wǒ suǒ liǎojiě de quánbù qíngkuàng.","vi":"Đây chính là toàn bộ tình hình mà tôi nắm được.","en":"This is everything I know about the situation."},{"zh":"他所提出的建议得到了领导的支持。","py":"Tā suǒ tíchū de jiànyì dédào le lǐngdǎo de zhīchí.","vi":"Đề xuất mà anh ấy đưa ra đã được lãnh đạo ủng hộ.","en":"The suggestion he put forward won the leadership's support."}],"quiz":[{"q":"据我____知，他下个月要辞职。","options":["所","被","把","而"],"answer":0,"explain":{"vi":"据我所知: theo như tôi được biết.","en":"据我所知: as far as I know."}},{"q":"下面哪个句子是正确的？","options":["所我担心的问题终于发生了。","我所担心的问题终于发生了。","我担心所的问题终于发生了。","我担心的所问题终于发生了。"],"answer":1,"explain":{"vi":"所 đứng sau chủ ngữ, ngay trước động từ.","en":"所 follows the subject and goes right before the verb."}},{"q":"“他所说的话”中，“所说的”指：","options":["他说话的地方","他说话的原因","听他说话的人","他说的内容"],"answer":3,"explain":{"vi":"所 + động từ + 的 chỉ đối tượng của hành động.","en":"所 + verb + 的 refers to the thing acted on."}},{"q":"大家____关心的，是明年的工资会不会增加。","options":["把","被","所","对"],"answer":2,"explain":{"vi":"所关心的: điều mà mọi người quan tâm.","en":"所关心的: what everyone cares about."}},{"q":"我们要对自己所____的每一件事负责。","options":["做","做了","做着","做完了"],"answer":0,"explain":{"vi":"Sau 所 là động từ nguyên dạng, rồi đến 的.","en":"所 takes a bare verb, followed by 的."}}]},
  {"id":"h5g05","title":{"zh":"“之”的常用结构","vi":"Các cấu trúc với 之","en":"Structures with 之"},"pattern":"最 + Adj + 的 + N + 之一 | A (与 B) + 之间 | …之前 / 之后 / 之中 / 之外 | Num + 分之 + Num / 百分之 + Num","explain":{"vi":"之 là chữ văn ngôn tương đương 的, nay dùng trong các cụm cố định: 之一 (một trong những), 之间 (giữa), 之后/之前, 之外, 百分之…. Lỗi hay gặp: theo tiếng Việt \"một trong những…\" đặt 之一 lên trước; 之一 luôn đứng cuối cụm (最好的员工之一).","en":"之 is a classical word equal to 的, now found in set phrases: 之一 (one of), 之间 (between), 之后/之前, 之外, 百分之…. Common mistake: putting 之一 first as in \"one of the…\"; it always ends the phrase (最好的员工之一)."},"examples":[{"zh":"他是我们公司最优秀的员工之一。","py":"Tā shì wǒmen gōngsī zuì yōuxiù de yuángōng zhī yī.","vi":"Anh ấy là một trong những nhân viên xuất sắc nhất của công ty chúng tôi.","en":"He is one of the best employees in our company."},{"zh":"百分之八十的员工对新制度表示满意。","py":"Bǎi fēn zhī bāshí de yuángōng duì xīn zhìdù biǎoshì mǎnyì.","vi":"Tám mươi phần trăm nhân viên tỏ ra hài lòng với chế độ mới.","en":"Eighty per cent of employees say they are satisfied with the new system."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["这是之一我最喜欢的电影。","这是我之一最喜欢的电影。","这是我最喜欢的电影之一。","这是我最喜欢之一的电影。"],"answer":2,"explain":{"vi":"之一 đứng cuối cụm danh từ.","en":"之一 comes at the end of the noun phrase."}},{"q":"今年公司的利润增长了百分____十五。","options":["的","分","于","之"],"answer":3,"explain":{"vi":"百分之 + số: … phần trăm.","en":"百分之 + number: … per cent."}},{"q":"同事____应该互相信任、互相帮助。","options":["之间","之一","之后","之外"],"answer":0,"explain":{"vi":"…之间: giữa… với nhau.","en":"…之间: between, among."}},{"q":"除了工资____，公司还提供免费午餐。","options":["之间","之外","之一","之中"],"answer":1,"explain":{"vi":"除了…之外: ngoài… ra.","en":"除了…之外: apart from …."}},{"q":"“三分之一”的意思是：","options":["一份里面的三份","三加一","第三个","三份里面的一份"],"answer":3,"explain":{"vi":"Số sau 分之 là tử số: một phần ba.","en":"The number after 分之 is the numerator: one third."}}]},
  {"id":"h5g06","title":{"zh":"动词 / 形容词 + 于","vi":"Động từ / tính từ + 于","en":"Verb / adjective + 于"},"pattern":"位于 + place | 高于 / 低于 / 大于 + N (comparison) | 善于 + V | 成立于 / 生于 + time | 用于 + purpose","explain":{"vi":"于 là giới từ văn viết đứng sau động từ hoặc tính từ: chỉ nơi chốn, thời gian (位于, 成立于), so sánh (高于 = cao hơn), lĩnh vực (善于, 用于). Lỗi hay gặp: vừa dùng 比 vừa dùng 于 (比去年高于 là sai); 高于去年 đã là câu so sánh.","en":"于 is a written preposition placed after a verb or adjective: place or time (位于, 成立于), comparison (高于 = higher than), field (善于, 用于). Common mistake: using 比 together with 于 (比去年高于 is wrong); 高于去年 is already a comparison."},"examples":[{"zh":"我们公司位于市中心，交通非常方便。","py":"Wǒmen gōngsī wèiyú shì zhōngxīn, jiāotōng fēicháng fāngbiàn.","vi":"Công ty chúng tôi nằm ở trung tâm thành phố, giao thông rất thuận tiện.","en":"Our company is located in the city centre, and transport is very convenient."},{"zh":"今年的平均工资高于去年。","py":"Jīnnián de píngjūn gōngzī gāo yú qùnián.","vi":"Lương bình quân năm nay cao hơn năm ngoái.","en":"This year's average pay is higher than last year's."}],"quiz":[{"q":"这家银行成立____一九九五年。","options":["从","自从","于","以"],"answer":2,"explain":{"vi":"成立于 + thời gian.","en":"成立于 + time."}},{"q":"下面哪个句子是正确的？","options":["他的成绩高于全班的平均水平。","他的成绩比全班的平均水平高于。","他的成绩高全班的平均水平于。","他的成绩于全班的平均水平高。"],"answer":0,"explain":{"vi":"高于 + đối tượng so sánh, không dùng thêm 比.","en":"高于 + the thing compared, with no 比."}},{"q":"她很善____和不同的人打交道。","options":["以","在","对","于"],"answer":3,"explain":{"vi":"善于 + động từ: giỏi về việc gì.","en":"善于 + verb: be good at."}},{"q":"这笔钱主要用____员工培训。","options":["以","于","从","被"],"answer":1,"explain":{"vi":"用于: dùng vào việc gì.","en":"用于: be used for."}},{"q":"“这座城市位于中国的南方”的意思是：","options":["这座城市比南方大","这座城市离南方很远","这座城市在中国的南方","这座城市来自南方"],"answer":2,"explain":{"vi":"位于 = nằm ở.","en":"位于 = be located in."}}]},
  {"id":"h5g07","title":{"zh":"以便 / 以免","vi":"以便 (để tiện) / 以免 (để tránh)","en":"以便 / 以免 (so that / so as not to)"},"pattern":"A，以便 + B (B is what you want) | A，以免 + B (B is what you want to avoid)","explain":{"vi":"Cả hai đứng đầu vế sau để nêu mục đích của vế trước. 以便: để việc B dễ thực hiện. 以免: để tránh việc B không hay xảy ra. Lỗi hay gặp: nhầm hai từ, hoặc đặt ở đầu câu như 为了.","en":"Both open the second clause and give the purpose of the first. 以便: so that B becomes possible. 以免: so that the unwanted B does not happen. Common mistake: mixing them up, or putting them at the start of the sentence like 为了."},"examples":[{"zh":"请留下您的电话，以便我们及时联系您。","py":"Qǐng liúxià nín de diànhuà, yǐbiàn wǒmen jíshí liánxì nín.","vi":"Xin để lại số điện thoại để chúng tôi tiện liên hệ kịp thời với ông.","en":"Please leave your phone number so that we can contact you promptly."},{"zh":"合同要仔细检查，以免出现错误。","py":"Hétong yào zǐxì jiǎnchá, yǐmiǎn chūxiàn cuòwù.","vi":"Hợp đồng phải kiểm tra kỹ để tránh xảy ra sai sót.","en":"Check the contract carefully so as to avoid mistakes."}],"quiz":[{"q":"出门前请检查一下门窗，____发生危险。","options":["以便","以免","以为","以及"],"answer":1,"explain":{"vi":"Điều muốn tránh (nguy hiểm) dùng 以免.","en":"Something to be avoided (danger) takes 以免."}},{"q":"请提前告诉我们人数，____我们安排座位。","options":["以便","以免","以来","以上"],"answer":0,"explain":{"vi":"Điều muốn thực hiện được (xếp chỗ) dùng 以便.","en":"Something you want to make possible takes 以便."}},{"q":"开会时请把手机关掉，以免____。","options":["方便大家","提高效率","节省时间","影响别人"],"answer":3,"explain":{"vi":"Sau 以免 là điều không mong muốn.","en":"以免 is followed by something unwanted."}},{"q":"下面哪个句子是正确的？","options":["以便我把地址写下来了，你能找到。","我把地址写下来了，你以便能找到。","我把地址写下来了，以便你能找到。","我以便把地址写下来了，你能找到。"],"answer":2,"explain":{"vi":"以便 đứng đầu vế sau, trước chủ ngữ của vế đó.","en":"以便 opens the second clause, before its subject."}},{"q":"“以免”的意思最接近：","options":["为了不让……发生","为了让……发生","因为……已经发生","虽然……会发生"],"answer":0,"explain":{"vi":"以免 = để khỏi, để tránh.","en":"以免 = in order to prevent."}}]},
  {"id":"h5g08","title":{"zh":"以来 / 至今","vi":"以来 (từ… đến nay) / 至今 (cho đến nay)","en":"以来 / 至今 (since / to this day)"},"pattern":"time point / event + 以来，… | 自 / 自从 + … + 以来 | S + 至今 + 还 / 仍 / 没 + V","explain":{"vi":"以来 đứng sau một mốc thời gian hay sự kiện trong quá khứ, chỉ khoảng thời gian từ đó kéo đến hiện tại. 至今 là phó từ \"cho đến bây giờ\". Lỗi hay gặp: dùng 以来 cho mốc ở tương lai (明年以来 là sai, phải dùng 以后).","en":"以来 follows a past time point or event and covers the period from then up to now. 至今 is an adverb, \"up to now\". Common mistake: using 以来 with a future point (明年以来 is wrong; use 以后)."},"examples":[{"zh":"今年以来，公司的业务发展得很快。","py":"Jīnnián yǐlái, gōngsī de yèwù fāzhǎn de hěn kuài.","vi":"Từ đầu năm đến nay, nghiệp vụ của công ty phát triển rất nhanh.","en":"Since the start of this year the company's business has grown fast."},{"zh":"这个问题至今没有得到解决。","py":"Zhège wèntí zhìjīn méiyǒu dédào jiějué.","vi":"Vấn đề này đến nay vẫn chưa được giải quyết.","en":"This problem has still not been solved to this day."}],"quiz":[{"q":"自从去年换了经理____，部门的气氛好多了。","options":["以免","以便","以及","以来"],"answer":3,"explain":{"vi":"自从…以来: kể từ… đến nay.","en":"自从…以来: ever since …."}},{"q":"他十年前离开了家乡，____没有回去过。","options":["以来","至今","以便","至于"],"answer":1,"explain":{"vi":"至今没有…过: đến nay vẫn chưa….","en":"至今没有…过: has not … to this day."}},{"q":"下面哪个句子是正确的？","options":["进入公司以来，她从来没有迟到过。","以来进入公司，她从来没有迟到过。","进入以来公司，她从来没有迟到过。","进入公司，她以来从来没有迟到过。"],"answer":0,"explain":{"vi":"以来 đứng ngay sau sự kiện làm mốc.","en":"以来 comes right after the event used as the starting point."}},{"q":"明年春节____，我打算换一份工作。","options":["以来","至今","以后","以便"],"answer":2,"explain":{"vi":"Mốc ở tương lai dùng 以后, không dùng 以来.","en":"A future point takes 以后, not 以来."}},{"q":"“至今”的意思是：","options":["从现在开始","一直到现在","到那个时候","很久以前"],"answer":1,"explain":{"vi":"至今 = cho đến bây giờ.","en":"至今 = up to the present."}}]},
  {"id":"h5g09","title":{"zh":"则","vi":"Liên từ / phó từ 则","en":"则 (whereas; then)"},"pattern":"A…，B + 则 + … (contrast) | 如 / 如果 + A，则 + B (formal 就)","explain":{"vi":"则 dùng trong văn viết. (1) Đối chiếu hai vế: 则 đứng sau chủ ngữ của vế sau, nghĩa \"còn… thì…\". (2) Trong câu điều kiện, 则 tương đương 就. Lỗi hay gặp: đặt 则 ở cuối câu hoặc sau động từ.","en":"则 belongs to written style. (1) Contrasting two clauses: 则 follows the subject of the second clause, \"whereas\". (2) In a conditional, 则 equals 就. Common mistake: putting 则 at the end of the sentence or after the verb."},"examples":[{"zh":"北方人喜欢吃面，南方人则喜欢吃米饭。","py":"Běifāngrén xǐhuan chī miàn, nánfāngrén zé xǐhuan chī mǐfàn.","vi":"Người miền Bắc thích ăn mì, còn người miền Nam thì thích ăn cơm.","en":"Northerners like noodles, whereas southerners like rice."},{"zh":"如不能按时完成，则需要提前说明。","py":"Rú bù néng ànshí wánchéng, zé xūyào tíqián shuōmíng.","vi":"Nếu không thể hoàn thành đúng hạn thì cần nói rõ trước.","en":"If it cannot be finished on time, this must be explained in advance."}],"quiz":[{"q":"哥哥性格安静，弟弟____非常活泼。","options":["即","便","所","则"],"answer":3,"explain":{"vi":"Đối chiếu hai người, 则 đứng sau chủ ngữ của vế sau.","en":"Contrasting two people: 则 follows the second subject."}},{"q":"下面哪个句子是正确的？","options":["有人赞成这个方案，有人则表示反对。","有人赞成这个方案，有人表示反对则。","有人赞成这个方案，有人表示则反对。","则有人赞成这个方案，有人表示反对。"],"answer":0,"explain":{"vi":"则 đứng sau chủ ngữ của vế sau, trước động từ.","en":"则 follows the subject of the second clause and precedes the verb."}},{"q":"“如发现问题，则应立即报告”中的“则”相当于：","options":["才","就","又","还"],"answer":1,"explain":{"vi":"Trong câu điều kiện, 则 = 就.","en":"In a conditional, 则 = 就."}},{"q":"工作日他很少运动，周末____常常去爬山。","options":["所","之","则","于"],"answer":2,"explain":{"vi":"Đối chiếu 工作日 với 周末.","en":"工作日 is contrasted with 周末."}},{"q":"这种做法短期内能降低成本，长期来看____可能带来风险。","options":["以","则","于","所"],"answer":1,"explain":{"vi":"Đối chiếu ngắn hạn với dài hạn.","en":"Short term is contrasted with long term."}}]},
  {"id":"h5g10","title":{"zh":"便","vi":"Phó từ 便 (= 就)","en":"便 (formal 就)"},"pattern":"S + 便 + V | 一 + V1，便 + V2 | 只要…，便…","explain":{"vi":"便 (biàn) là phó từ văn viết, nghĩa và cách dùng giống 就: việc xảy ra ngay sau đó, hoặc kết quả của một điều kiện. 便 đứng sau chủ ngữ, trước động từ. Lỗi hay gặp: đặt 便 trước chủ ngữ.","en":"便 (biàn) is a written adverb with the meaning and use of 就: something follows at once, or results from a condition. It goes after the subject and before the verb. Common mistake: putting 便 before the subject."},"examples":[{"zh":"他大学毕业后便进入了这家公司。","py":"Tā dàxué bìyè hòu biàn jìnrù le zhè jiā gōngsī.","vi":"Sau khi tốt nghiệp đại học, anh ấy liền vào công ty này.","en":"He joined this company right after graduating from university."},{"zh":"她一听到这个消息，便立刻赶了过来。","py":"Tā yì tīngdào zhège xiāoxi, biàn lìkè gǎn le guòlai.","vi":"Vừa nghe tin này, cô ấy liền lập tức chạy đến.","en":"As soon as she heard the news, she hurried over."}],"quiz":[{"q":"“说完，他便离开了”中的“便”相当于：","options":["才","还","却","就"],"answer":3,"explain":{"vi":"便 = 就 trong văn viết.","en":"便 = 就 in written style."}},{"q":"他一下班____回家照顾孩子。","options":["而","便","则","所"],"answer":1,"explain":{"vi":"一…便…: vừa… liền….","en":"一…便…: as soon as…."}},{"q":"下面哪个句子是正确的？","options":["天一亮，便他们出发了。","天一亮，他们出发便了。","天一亮，他们便出发了。","便天一亮，他们出发了。"],"answer":2,"explain":{"vi":"便 đứng sau chủ ngữ, trước động từ.","en":"便 follows the subject and precedes the verb."}},{"q":"只要有时间，她____去图书馆看书。","options":["便","才","却","而"],"answer":0,"explain":{"vi":"只要…便…: chỉ cần… là….","en":"只要…便…: whenever … then …."}},{"q":"“便”作副词时，常常用在：","options":["只在问句里","只在否定句里","只在口语里","比较正式的文章里"],"answer":3,"explain":{"vi":"便 là cách nói trang trọng của 就.","en":"便 is the formal counterpart of 就."}}]},
  {"id":"h5g11","title":{"zh":"未必 / 不见得","vi":"未必 / 不见得 (chưa chắc)","en":"未必 / 不见得 (not necessarily)"},"pattern":"S + 未必 / 不见得 + V / Adj | 那倒未必。","explain":{"vi":"Phủ định nhẹ nhàng một nhận định: \"chưa chắc, không hẳn\". 未必 là văn viết, 不见得 là khẩu ngữ. Lỗi hay gặp: hiểu 未必 là \"chắc chắn không\"; 未必 = 不一定, không phải 一定不.","en":"Politely doubts a claim: \"not necessarily\". 未必 is written style, 不见得 spoken. Common mistake: reading 未必 as \"certainly not\"; 未必 = 不一定, not 一定不."},"examples":[{"zh":"价格高的产品质量未必好。","py":"Jiàgé gāo de chǎnpǐn zhìliàng wèibì hǎo.","vi":"Sản phẩm giá cao thì chất lượng chưa chắc đã tốt.","en":"An expensive product is not necessarily good quality."},{"zh":"他说得很有道理，但不见得适合我们。","py":"Tā shuō de hěn yǒu dàolǐ, dàn bújiànde shìhé wǒmen.","vi":"Anh ấy nói rất có lý, nhưng chưa chắc đã hợp với chúng ta.","en":"What he says makes sense, but it may not suit us."}],"quiz":[{"q":"“他未必知道这件事”的意思是：","options":["他一定不知道","他不一定知道","他一定知道","他不想知道"],"answer":1,"explain":{"vi":"未必 = 不一定 (chưa chắc).","en":"未必 = 不一定 (not necessarily)."}},{"q":"经验丰富的人____不会犯错误。","options":["未必","何必","不必","务必"],"answer":0,"explain":{"vi":"未必不会 = chưa chắc là không (vẫn có thể mắc lỗi).","en":"未必不会 = may still (make mistakes)."}},{"q":"你觉得好的方法，别人____觉得好。","options":["不由得","恨不得","舍不得","不见得"],"answer":3,"explain":{"vi":"不见得 = chưa chắc.","en":"不见得 = not necessarily."}},{"q":"广告做得好，产品却____好。","options":["必须","必然","未必","必要"],"answer":2,"explain":{"vi":"Có 却 chỉ ý trái lại, nên dùng 未必.","en":"却 signals a contrast, so 未必 fits."}},{"q":"A：他肯定会同意的。B：____，他最近意见很多。","options":["那当然","那倒未必","没错","可不是"],"answer":1,"explain":{"vi":"那倒未必: cái đó thì chưa chắc.","en":"那倒未必: that's not necessarily so."}}]},
  {"id":"h5g12","title":{"zh":"难免 / 未免","vi":"难免 (khó tránh khỏi) / 未免 (có phần hơi quá)","en":"难免 / 未免 (hard to avoid / rather too)"},"pattern":"难免 + (会 / 要) + V | …是难免的 | 未免 + 太 / 过于 / 有些 + Adj","explain":{"vi":"难免: việc không hay rất khó tránh, là điều tự nhiên. 未免: người nói chê nhẹ rằng điều gì đó hơi quá mức, thường đi với 太, 过于, 有些. Lỗi hay gặp: nhầm 未免 với 难免 hay 以免 (để tránh).","en":"难免: something unwelcome is hard to avoid and only natural. 未免: the speaker mildly criticises something as rather excessive, usually with 太, 过于, 有些. Common mistake: confusing 未免 with 难免 or 以免 (so as not to)."},"examples":[{"zh":"刚开始工作，难免会遇到一些困难。","py":"Gāng kāishǐ gōngzuò, nánmiǎn huì yùdào yìxiē kùnnan.","vi":"Mới bắt đầu đi làm thì khó tránh khỏi gặp một số khó khăn.","en":"When you have just started work, some difficulties are unavoidable."},{"zh":"只给三天时间，这个要求未免太高了。","py":"Zhǐ gěi sān tiān shíjiān, zhège yāoqiú wèimiǎn tài gāo le.","vi":"Chỉ cho ba ngày, yêu cầu này có phần quá cao rồi.","en":"Only three days? That requirement is rather too demanding."}],"quiz":[{"q":"第一次上台讲话，____会有点儿紧张。","options":["何必","以免","避免","难免"],"answer":3,"explain":{"vi":"难免会…: khó tránh khỏi việc….","en":"难免会…: it is hard not to…."}},{"q":"你这样说，____太不客气了。","options":["未免","难免","以免","避免"],"answer":0,"explain":{"vi":"Chê nhẹ \"hơi quá\" dùng 未免太….","en":"Mild criticism, \"rather too\", takes 未免太…."}},{"q":"“人难免会犯错误”的意思是：","options":["人不会犯错误","人不应该犯错误","人很难不犯错误","人很难犯错误"],"answer":2,"explain":{"vi":"难免 = khó mà tránh được.","en":"难免 = can hardly be avoided."}},{"q":"为了一点儿小事就发脾气，____有些过分。","options":["以免","未免","避免","难道"],"answer":1,"explain":{"vi":"未免有些过分: có phần hơi quá đáng.","en":"未免有些过分: rather over the top."}},{"q":"两个人一起工作，意见不同是____的。","options":["难免","未免","以免","何必"],"answer":0,"explain":{"vi":"…是难免的: … là điều khó tránh.","en":"…是难免的: … is only to be expected."}}]},
  {"id":"h5g13","title":{"zh":"何必 / 何况","vi":"何必 (việc gì phải) / 何况 (huống chi)","en":"何必 / 何况 (why bother / let alone)"},"pattern":"(S) + 何必 + V + 呢？ | A 都 / 也…，何况 + B (+ 呢)？","explain":{"vi":"何必: câu hỏi tu từ, ý là \"không cần phải…\". 何况: đưa thêm trường hợp càng rõ hơn: \"huống chi, hơn nữa\". Lỗi hay gặp: nhầm 何必 với 不必 trong câu có 呢, hoặc dùng 何况 khi không có vế trước để so sánh.","en":"何必: a rhetorical question meaning \"there is no need to…\". 何况: brings in an even clearer case: \"let alone, besides\". Common mistake: mixing 何必 with 不必 in a 呢 question, or using 何况 with nothing before it to compare with."},"examples":[{"zh":"都是同事，何必为这点儿小事生气呢？","py":"Dōu shì tóngshì, hébì wèi zhè diǎnr xiǎoshì shēngqì ne?","vi":"Đều là đồng nghiệp cả, việc gì phải giận nhau vì chuyện nhỏ này?","en":"We're all colleagues; why get angry over such a small thing?"},{"zh":"大人都搬不动，何况一个孩子呢？","py":"Dàren dōu bān bu dòng, hékuàng yí ge háizi ne?","vi":"Người lớn còn không bê nổi, huống chi là một đứa trẻ?","en":"Even an adult can't move it, let alone a child."}],"quiz":[{"q":"“你何必亲自去呢？”的意思是：","options":["你必须亲自去","你为什么不亲自去","你不需要亲自去","你什么时候亲自去"],"answer":2,"explain":{"vi":"何必…呢 = không cần phải….","en":"何必…呢 = there is no need to…."}},{"q":"这个问题连专家都回答不了，____我们呢？","options":["何必","尽管","难道","何况"],"answer":3,"explain":{"vi":"连 A 都…，何况 B: đến A còn…, huống chi B.","en":"连 A 都…，何况 B: even A…, let alone B."}},{"q":"既然他已经道歉了，你____还生气呢？","options":["何必","何况","未必","不必"],"answer":0,"explain":{"vi":"Câu hỏi tu từ khuyên \"không cần\" dùng 何必…呢.","en":"A rhetorical \"why bother\" takes 何必…呢."}},{"q":"平时这条路就堵车，____今天还下着大雨。","options":["何必","何况","未必","难免"],"answer":1,"explain":{"vi":"何况 bổ sung một lý do mạnh hơn.","en":"何况 adds a stronger reason."}},{"q":"下面哪个句子是正确的？","options":["何必走路只要五分钟，打车呢？","走路只要五分钟，打何必车呢？","走路只要五分钟，何必打车呢？","走路何必只要五分钟，打车呢？"],"answer":2,"explain":{"vi":"何必 đứng trước động từ của việc không cần làm.","en":"何必 goes before the verb of the unnecessary action."}}]},
  {"id":"h5g14","title":{"zh":"反正","vi":"Phó từ 反正 (dù sao thì)","en":"反正 (anyway, in any case)"},"pattern":"不管 / 无论…，反正 + clause | 反正 + reason，+ suggestion","explain":{"vi":"反正: dù tình hình thế nào thì kết luận vẫn không đổi; cũng dùng để nêu một lý do hiển nhiên trước khi đề nghị. Thường đứng đầu vế câu. Lỗi hay gặp: nhầm với 反而 (trái lại, ngược với dự đoán).","en":"反正: whatever the situation, the conclusion stays the same; it also gives an obvious reason before a suggestion. It usually opens the clause. Common mistake: confusing it with 反而 (on the contrary, against expectation)."},"examples":[{"zh":"不管你去不去，反正我是要去的。","py":"Bùguǎn nǐ qù bu qù, fǎnzhèng wǒ shì yào qù de.","vi":"Dù bạn có đi hay không, dù sao tôi cũng sẽ đi.","en":"Whether you go or not, I'm going anyway."},{"zh":"反正时间还早，我们走着去吧。","py":"Fǎnzhèng shíjiān hái zǎo, wǒmen zǒu zhe qù ba.","vi":"Dù sao vẫn còn sớm, chúng ta đi bộ đến đó đi.","en":"It's still early anyway, so let's walk there."}],"quiz":[{"q":"你想说什么就说吧，____大家都是朋友。","options":["反而","反对","相反","反正"],"answer":3,"explain":{"vi":"Nêu lý do hiển nhiên \"dù sao thì\" dùng 反正.","en":"Giving an obvious reason, \"anyway\", takes 反正."}},{"q":"信不信由你，____我说的都是真的。","options":["反正","反而","反映","反复"],"answer":0,"explain":{"vi":"Dù tin hay không, kết luận không đổi: 反正.","en":"Believe it or not, the conclusion stands: 反正."}},{"q":"吃了药，他的病不但没好，____更严重了。","options":["反正","反而","反对","反复"],"answer":1,"explain":{"vi":"Kết quả trái với mong đợi dùng 反而.","en":"A result opposite to what was expected takes 反而."}},{"q":"“反正”表示：","options":["结果和想的相反","事情重复发生","不管情况怎么样，结果都一样","不同意别人的看法"],"answer":2,"explain":{"vi":"反正 = dù thế nào thì kết quả cũng vậy.","en":"反正 = whatever happens, the outcome is the same."}},{"q":"____明天不上班，今天晚点儿睡也没关系。","options":["反正","反而","否则","何况"],"answer":0,"explain":{"vi":"反正 nêu lý do để yên tâm làm việc gì.","en":"反正 gives the reason why something is fine."}}]},
  {"id":"h5g15","title":{"zh":"毕竟","vi":"Phó từ 毕竟 (suy cho cùng)","en":"毕竟 (after all)"},"pattern":"S + 毕竟 + 是 / V… | A 毕竟是 A","explain":{"vi":"Nhấn mạnh một sự thật hay lý do quyết định mà không thể bỏ qua: \"dù sao thì, suy cho cùng\". Thường dùng để giải thích, bênh vực. Lỗi hay gặp: nhầm với 终于 (cuối cùng cũng xảy ra) hoặc dùng trong câu hỏi như 究竟.","en":"Stresses the decisive fact or reason that cannot be ignored: \"after all\". Often used to explain or excuse. Common mistake: confusing it with 终于 (finally happened) or using it in questions like 究竟."},"examples":[{"zh":"别批评他了，他毕竟是第一次做这种工作。","py":"Bié pīpíng tā le, tā bìjìng shì dì yī cì zuò zhè zhǒng gōngzuò.","vi":"Đừng phê bình cậu ấy nữa, dù sao cậu ấy cũng mới làm việc này lần đầu.","en":"Don't criticise him; after all, this is his first time doing this kind of work."},{"zh":"虽然辛苦，但这毕竟是我自己的选择。","py":"Suīrán xīnkǔ, dàn zhè bìjìng shì wǒ zìjǐ de xuǎnzé.","vi":"Tuy vất vả, nhưng suy cho cùng đây là lựa chọn của chính tôi.","en":"It is hard, but after all it was my own choice."}],"quiz":[{"q":"他____还是个孩子，你别对他要求太高。","options":["终于","竟然","何必","毕竟"],"answer":3,"explain":{"vi":"Nêu lý do quyết định để bênh vực dùng 毕竟.","en":"Giving the decisive reason as an excuse takes 毕竟."}},{"q":"你____想不想参加这次培训？","options":["毕竟","究竟","反正","总算"],"answer":1,"explain":{"vi":"Trong câu hỏi truy vấn dùng 究竟, không dùng 毕竟.","en":"A pressing question takes 究竟, not 毕竟."}},{"q":"等了两个小时，公共汽车____来了。","options":["终于","毕竟","反正","未必"],"answer":0,"explain":{"vi":"Sau khi chờ lâu, việc cuối cùng cũng xảy ra: 终于.","en":"After a long wait it finally happened: 终于."}},{"q":"机器____是机器，不能完全代替人。","options":["终于","陆续","毕竟","逐渐"],"answer":2,"explain":{"vi":"A 毕竟是 A: A suy cho cùng vẫn là A.","en":"A 毕竟是 A: A is still A after all."}},{"q":"“毕竟”常用来：","options":["提出问题","强调最重要的原因或事实","表示事情很快发生","表示数量很多"],"answer":1,"explain":{"vi":"毕竟 nhấn mạnh lý do, sự thật mang tính quyết định.","en":"毕竟 stresses the decisive reason or fact."}}]},
  {"id":"h5g16","title":{"zh":"总算 / 终于","vi":"总算 / 终于 (cuối cùng cũng)","en":"总算 / 终于 (at long last / finally)"},"pattern":"S + 总算 + V + 了 (hoped-for result, relief) | S + 终于 + V + 了 | 总算 + 还 / 不错 (just about acceptable)","explain":{"vi":"Cả hai nói việc xảy ra sau thời gian dài chờ đợi, cố gắng. 总算 chỉ dùng cho kết quả mong muốn, có ý thở phào; còn có nghĩa \"tạm coi là được\". 终于 trung tính hơn, dùng được cho cả kết quả xấu. Lỗi hay gặp: dùng 总算 cho kết quả không mong muốn (他总算失败了 là sai).","en":"Both say something happened after long waiting or effort. 总算 is only for a hoped-for result and carries relief; it can also mean \"just about acceptable\". 终于 is more neutral and also works for bad outcomes. Common mistake: using 总算 for an unwanted result (他总算失败了 is wrong)."},"examples":[{"zh":"忙了一个月，这个项目总算完成了。","py":"Máng le yí ge yuè, zhège xiàngmù zǒngsuàn wánchéng le.","vi":"Bận rộn suốt một tháng, dự án này cuối cùng cũng xong.","en":"After a busy month, the project is finished at last."},{"zh":"经过多次修改，方案终于通过了。","py":"Jīngguò duō cì xiūgǎi, fāng'àn zhōngyú tōngguò le.","vi":"Sau nhiều lần sửa đổi, phương án cuối cùng đã được thông qua.","en":"After many revisions, the proposal was finally approved."}],"quiz":[{"q":"找了半天，我____找到了那份合同。","options":["反而","毕竟","总算","未必"],"answer":2,"explain":{"vi":"Kết quả mong muốn sau khi cố gắng lâu: 总算.","en":"A hoped-for result after long effort: 总算."}},{"q":"“雨总算停了”说明说话人：","options":["一直希望雨停","不希望雨停","没注意下雨","觉得雨下得太少"],"answer":0,"explain":{"vi":"总算 cho thấy đây là điều người nói mong đợi.","en":"总算 shows this is what the speaker was hoping for."}},{"q":"下面哪个句子是正确的？","options":["问题解决总算了。","总算了问题解决。","问题解决了总算。","问题总算解决了。"],"answer":3,"explain":{"vi":"总算 đứng sau chủ ngữ, trước động từ.","en":"总算 follows the subject and precedes the verb."}},{"q":"这次考试虽然分数不高，但____及格了。","options":["反而","总算","何必","难免"],"answer":1,"explain":{"vi":"总算 = tạm coi là đạt được.","en":"总算 = at least it was achieved."}},{"q":"下面哪句话里不能用“总算”？","options":["等了一个小时，他____来了。","我____明白了你的意思。","他努力了很久，可是____失败了。","孩子____睡着了。"],"answer":2,"explain":{"vi":"总算 không dùng cho kết quả không mong muốn như 失败.","en":"总算 is not used for an unwanted result such as 失败."}}]},
  {"id":"h5g17","title":{"zh":"一旦……就","vi":"Một khi… thì…","en":"一旦…就 (once… then…)"},"pattern":"(S) + 一旦 + condition，(S) + 就 + result","explain":{"vi":"Giả định một việc chưa biết lúc nào xảy ra; hễ xảy ra thì có kết quả ngay, thường là hệ quả quan trọng. 一旦 đứng trước hoặc sau chủ ngữ. Lỗi hay gặp: nhầm với 一…就 (hai việc thật xảy ra liền nhau, như 我一下班就回家).","en":"Supposes an event whose time is unknown; if it ever happens, the result follows, usually a weighty one. 一旦 goes before or after the subject. Common mistake: confusing it with 一…就 (two real events in quick succession, as in 我一下班就回家)."},"examples":[{"zh":"一旦发现问题，就要马上向领导报告。","py":"Yídàn fāxiàn wèntí, jiù yào mǎshàng xiàng lǐngdǎo bàogào.","vi":"Một khi phát hiện vấn đề thì phải báo cáo ngay với lãnh đạo.","en":"Once a problem is found, it must be reported to the leadership at once."},{"zh":"习惯一旦形成，就很难改变。","py":"Xíguàn yídàn xíngchéng, jiù hěn nán gǎibiàn.","vi":"Thói quen một khi đã hình thành thì rất khó thay đổi.","en":"Once a habit is formed, it is hard to change."}],"quiz":[{"q":"合同____签字，就不能随便修改了。","options":["一旦","一直","一向","一律"],"answer":0,"explain":{"vi":"一旦…就…: một khi… thì….","en":"一旦…就…: once… then…."}},{"q":"一旦错过这次机会，____很难再有了。","options":["才","却","而","就"],"answer":3,"explain":{"vi":"一旦 đi với 就 ở vế sau.","en":"一旦 pairs with 就 in the second clause."}},{"q":"下面哪个句子是正确的？","options":["信任失去一旦，就很难再建立。","信任一旦失去，就很难再建立。","一旦信任失去就，很难再建立。","信任一旦失去，很难就再建立。"],"answer":1,"explain":{"vi":"一旦 đứng trước động từ của vế điều kiện; 就 đứng đầu vế kết quả.","en":"一旦 precedes the verb of the condition; 就 opens the result."}},{"q":"“一旦”后面说的情况常常是：","options":["已经发生很久的","每天都发生的","还没发生、可能发生的","不可能发生的"],"answer":2,"explain":{"vi":"一旦 nêu một giả định có thể xảy ra.","en":"一旦 introduces something that may happen."}},{"q":"药品一旦过期，就____。","options":["可以继续吃","不能再吃了","曾经吃过","正在吃"],"answer":1,"explain":{"vi":"Vế sau là hệ quả tất yếu của điều kiện.","en":"The second clause is the necessary consequence."}}]},
  {"id":"h5g18","title":{"zh":"假如……就 / 万一","vi":"假如 (giả sử) / 万一 (lỡ như)","en":"假如…就 / 万一 (suppose / just in case)"},"pattern":"假如 + hypothesis，(S) + 就 / 会 + result | 万一 + unlikely event，(S) + 就… | …，万一…呢？","explain":{"vi":"假如: giả thiết nói chung, kể cả điều trái với thực tế, trang trọng hơn 如果. 万一: khả năng rất nhỏ, thường là việc không mong muốn, dùng khi đề phòng. Lỗi hay gặp: dùng 万一 cho giả thiết trái thực tế (万一我是你 là sai, phải nói 假如我是你).","en":"假如: a general supposition, including things contrary to fact; more formal than 如果. 万一: a very small chance, usually of something unwanted, used when taking precautions. Common mistake: using 万一 for a contrary-to-fact supposition (万一我是你 is wrong; say 假如我是你)."},"examples":[{"zh":"假如我是你，就会接受这份工作。","py":"Jiǎrú wǒ shì nǐ, jiù huì jiēshòu zhè fèn gōngzuò.","vi":"Giả sử tôi là bạn, tôi sẽ nhận công việc này.","en":"If I were you, I would accept this job."},{"zh":"带上雨伞吧，万一下午下雨呢。","py":"Dài shang yǔsǎn ba, wànyī xiàwǔ xià yǔ ne.","vi":"Mang ô theo đi, lỡ buổi chiều trời mưa thì sao.","en":"Take an umbrella, just in case it rains this afternoon."}],"quiz":[{"q":"____你是经理，你会怎么处理这件事？","options":["万一","哪怕","除非","假如"],"answer":3,"explain":{"vi":"Giả thiết trái với thực tế dùng 假如.","en":"A contrary-to-fact supposition takes 假如."}},{"q":"你把资料多复印一份，____弄丢了还有一份。","options":["万一","除非","尽管","固然"],"answer":0,"explain":{"vi":"Đề phòng việc ít khả năng xảy ra dùng 万一.","en":"Guarding against an unlikely event takes 万一."}},{"q":"“万一”表示的可能性：","options":["很大","很小","百分之百","完全没有"],"answer":1,"explain":{"vi":"万一 = một phần vạn, khả năng rất nhỏ.","en":"万一 = one in ten thousand, a very small chance."}},{"q":"假如时间可以回到过去，你____做什么？","options":["了","过","会","着"],"answer":2,"explain":{"vi":"假如…会…: giả sử… thì sẽ….","en":"假如…会…: if…, would…."}},{"q":"不怕一万，就怕____。","options":["一万","一旦","假如","万一"],"answer":3,"explain":{"vi":"Tục ngữ: không sợ mười nghìn, chỉ sợ một phần vạn (phải đề phòng điều hiếm khi xảy ra).","en":"A saying: be prepared for the one-in-ten-thousand chance."}}]},
  {"id":"h5g19","title":{"zh":"哪怕……也","vi":"Dù cho… cũng…","en":"哪怕…也 (even if)"},"pattern":"哪怕 + extreme hypothesis，(S) + 也 / 都 + V | main clause，哪怕 + …","explain":{"vi":"Nêu giả thiết ở mức cực đoan, kết quả vẫn không đổi; khẩu ngữ hơn 即使. Vế sau phải có 也 hoặc 都. Lỗi hay gặp: vế sau dùng 但是 hoặc 就 thay cho 也.","en":"Sets up an extreme supposition under which the result still holds; more colloquial than 即使. The second clause needs 也 or 都. Common mistake: using 但是 or 就 instead of 也."},"examples":[{"zh":"哪怕只有一个人来，活动也要照常进行。","py":"Nǎpà zhǐyǒu yí ge rén lái, huódòng yě yào zhàocháng jìnxíng.","vi":"Dù chỉ có một người đến, hoạt động vẫn phải tiến hành như thường.","en":"Even if only one person comes, the event will go ahead as usual."},{"zh":"哪怕再忙，他每天也要陪孩子聊聊天。","py":"Nǎpà zài máng, tā měi tiān yě yào péi háizi liáoliao tiān.","vi":"Dù bận đến mấy, ngày nào anh ấy cũng trò chuyện với con.","en":"However busy he is, he chats with his child every day."}],"quiz":[{"q":"哪怕工资低一点儿，我____愿意做自己喜欢的工作。","options":["就","也","才","却"],"answer":1,"explain":{"vi":"哪怕 đi với 也.","en":"哪怕 pairs with 也."}},{"q":"____明天下大雪，比赛也不会取消。","options":["除非","既然","哪怕","由于"],"answer":2,"explain":{"vi":"Giả thiết cực đoan mà kết quả không đổi: 哪怕…也.","en":"An extreme supposition with an unchanged result: 哪怕…也."}},{"q":"下面哪个句子是正确的？","options":["哪怕失败一百次，我也不会放弃。","哪怕失败一百次，但是我不会放弃。","我哪怕也失败一百次，不会放弃。","哪怕失败一百次，我就不会放弃。"],"answer":0,"explain":{"vi":"Vế sau dùng 也, đứng sau chủ ngữ.","en":"The second clause uses 也, after the subject."}},{"q":"“哪怕”的意思和下面哪个词最接近？","options":["除非","由于","何况","即使"],"answer":3,"explain":{"vi":"哪怕 ≈ 即使 (dù cho).","en":"哪怕 ≈ 即使 (even if)."}},{"q":"你来看看我吧，哪怕____。","options":["只待了十分钟","只待十分钟也好","因为太忙","所以不来"],"answer":1,"explain":{"vi":"哪怕 có thể đứng ở vế sau, nêu mức tối thiểu.","en":"哪怕 can come second, giving the minimum acceptable."}}]},
  {"id":"h5g20","title":{"zh":"除非……否则 / 才","vi":"Trừ phi… nếu không / mới","en":"除非…否则 / 才 (unless / only if)"},"pattern":"除非 + A，否则 / 不然 + (不) B | 除非 + A，(S) + 才 + B","explain":{"vi":"除非 nêu điều kiện duy nhất. 除非A，才B: chỉ khi có A thì mới B. 除非A，否则不B: trừ phi A, nếu không thì không B. Lỗi hay gặp: lẫn lộn hai kiểu (除非你去，否则我才去 là sai).","en":"除非 gives the one condition that matters. 除非A，才B: only if A will B happen. 除非A，否则不B: unless A, B will not happen. Common mistake: mixing the two (除非你去，否则我才去 is wrong)."},"examples":[{"zh":"除非你亲自去请，否则他不会来的。","py":"Chúfēi nǐ qīnzì qù qǐng, fǒuzé tā bú huì lái de.","vi":"Trừ phi bạn đích thân đi mời, nếu không anh ấy sẽ không đến đâu.","en":"Unless you go and invite him yourself, he won't come."},{"zh":"除非有特殊情况，我才会请假。","py":"Chúfēi yǒu tèshū qíngkuàng, wǒ cái huì qǐngjià.","vi":"Chỉ khi có tình huống đặc biệt, tôi mới xin nghỉ.","en":"Only in special circumstances do I ask for leave."}],"quiz":[{"q":"除非老板同意，____我们不能提前下班。","options":["才","就","否则","也"],"answer":2,"explain":{"vi":"除非…否则不…: trừ phi… nếu không thì không….","en":"除非…否则不…: unless…, otherwise not…."}},{"q":"除非你答应保密，我____告诉你。","options":["才","否则","却","而"],"answer":0,"explain":{"vi":"除非…才…: chỉ khi… mới….","en":"除非…才…: only if… will…."}},{"q":"“除非下雨，否则我每天都跑步”的意思是：","options":["下雨的时候我才跑步","我每天都不跑步","下雨我也跑步","只有下雨的时候我不跑步"],"answer":3,"explain":{"vi":"Điều kiện duy nhất khiến tôi không chạy là trời mưa.","en":"Rain is the only thing that stops me running."}},{"q":"____亲眼看到，否则我不会相信。","options":["哪怕","除非","既然","假如"],"answer":1,"explain":{"vi":"Vế sau có 否则 nên vế trước dùng 除非.","en":"The second clause has 否则, so the first takes 除非."}},{"q":"下面哪个句子是正确的？","options":["除非你道歉，才我不会原谅你。","否则你道歉，除非我不会原谅你。","除非你道歉，否则我不会原谅你。","除非你道歉，否则我才原谅你。"],"answer":2,"explain":{"vi":"Cấu trúc đúng: 除非 A，否则 + 不 B.","en":"The correct pattern: 除非 A，否则 + 不 B."}}]},
  {"id":"h5g21","title":{"zh":"要不是","vi":"Nếu không phải vì…","en":"要不是 (if it weren't for)"},"pattern":"要不是 + real fact，(S) + 就 / 早就 / 还 / 也 + unreal result","explain":{"vi":"Sau 要不是 là việc có thật; vế sau là điều lẽ ra đã xảy ra nếu không có việc đó. Thường dùng để cảm ơn hoặc trách. Lỗi hay gặp: hiểu như giả thiết mở \"nếu không…\" (trường hợp đó dùng 如果不…).","en":"What follows 要不是 is a real fact; the second clause says what would have happened without it. Often used to thank or to blame. Common mistake: treating it as an open condition \"if not…\" (that is 如果不…)."},"examples":[{"zh":"要不是你提醒我，我就忘了今天的会议。","py":"Yàobúshì nǐ tíxǐng wǒ, wǒ jiù wàng le jīntiān de huìyì.","vi":"Nếu không nhờ bạn nhắc, tôi đã quên mất cuộc họp hôm nay.","en":"If you hadn't reminded me, I would have forgotten today's meeting."},{"zh":"要不是堵车，我们早就到机场了。","py":"Yàobúshì dǔchē, wǒmen zǎo jiù dào jīchǎng le.","vi":"Nếu không phải vì tắc đường, chúng tôi đã đến sân bay từ lâu rồi.","en":"If it weren't for the traffic jam, we would have reached the airport long ago."}],"quiz":[{"q":"“要不是你帮忙，我完成不了”说明：","options":["你没帮忙，我没完成","你帮忙了，我没完成","你没帮忙，我完成了","你帮忙了，我完成了"],"answer":3,"explain":{"vi":"Việc sau 要不是 là có thật; vế sau là điều đã không xảy ra.","en":"What follows 要不是 is real; the second clause did not happen."}},{"q":"____下雨，我们现在已经在爬山了。","options":["要是","要不是","除非","哪怕"],"answer":1,"explain":{"vi":"Thực tế là trời mưa nên không leo núi được: 要不是.","en":"It did rain, so they are not climbing: 要不是."}},{"q":"要不是医生来得及时，他____有生命危险了。","options":["就","才","却","而"],"answer":0,"explain":{"vi":"要不是…就…: nếu không… thì đã….","en":"要不是…就…: if not for…, would have…."}},{"q":"下面哪个句子是正确的？","options":["他告诉我要不是，我还不知道这件事呢。","不是要他告诉我，我还不知道这件事呢。","要不是他告诉我，我还不知道这件事呢。","要不是他告诉我，我已经知道这件事呢。"],"answer":2,"explain":{"vi":"要不是 đứng đầu vế trước; vế sau nêu điều trái với thực tế.","en":"要不是 opens the first clause; the second states what is contrary to fact."}},{"q":"要不是为了孩子，她____搬到这么远的地方。","options":["一定","不会","已经","正在"],"answer":1,"explain":{"vi":"Thực tế là cô ấy đã chuyển đi vì con; nếu không thì sẽ không chuyển.","en":"She did move, for the child's sake; otherwise she would not have."}}]},
  {"id":"h5g22","title":{"zh":"凡是……都","vi":"Hễ là… đều…","en":"凡是…都 (every, whoever, whatever)"},"pattern":"凡是 + (…的) + N，都 / 一律 + V","explain":{"vi":"Chỉ tất cả những gì thuộc một phạm vi, không có ngoại lệ. 凡是 đứng đầu câu, trước cụm danh từ; vế sau thường có 都. Lỗi hay gặp: bỏ 都 hoặc đặt 凡是 sau danh từ.","en":"Covers everything within a range, with no exception. 凡是 opens the sentence, before the noun phrase; the main clause usually has 都. Common mistake: dropping 都 or placing 凡是 after the noun."},"examples":[{"zh":"凡是参加培训的员工，都要提前报名。","py":"Fánshì cānjiā péixùn de yuángōng, dōu yào tíqián bàomíng.","vi":"Hễ là nhân viên tham gia đào tạo đều phải đăng ký trước.","en":"All employees who join the training must sign up in advance."},{"zh":"凡是她答应的事，没有做不到的。","py":"Fánshì tā dāying de shì, méiyǒu zuò bu dào de.","vi":"Hễ là việc cô ấy đã hứa thì không có việc nào không làm được.","en":"Whatever she promises, she always delivers."}],"quiz":[{"q":"____去过那儿的人，都说风景很美。","options":["尽管","凡是","哪怕","除非"],"answer":1,"explain":{"vi":"凡是…都…: hễ là… đều….","en":"凡是…都…: everyone who…."}},{"q":"凡是公司的规定，大家____应该遵守。","options":["才","却","便","都"],"answer":3,"explain":{"vi":"凡是 đi với 都.","en":"凡是 pairs with 都."}},{"q":"下面哪个句子是正确的？","options":["凡是迟到的人，都要说明原因。","迟到的人凡是，都要说明原因。","凡是迟到的人，才要说明原因。","迟到凡是的人，都要说明原因。"],"answer":0,"explain":{"vi":"凡是 đứng đầu câu, vế sau dùng 都.","en":"凡是 opens the sentence and the main clause has 都."}},{"q":"“凡是”的意思是：","options":["只有一个","大部分","只要是、所有的","没有一个"],"answer":2,"explain":{"vi":"凡是 = tất cả những gì thuộc phạm vi đó.","en":"凡是 = all that fall within the range."}},{"q":"凡是有利于提高效率的建议，我们____。","options":["才欢迎过","都欢迎","却欢迎","何必欢迎"],"answer":1,"explain":{"vi":"Vế sau dùng 都 để chỉ không có ngoại lệ.","en":"The main clause uses 都 for \"without exception\"."}}]},
  {"id":"h5g23","title":{"zh":"不但不 / 没……反而……","vi":"Không những không… mà trái lại…","en":"不但不 / 没…反而… (far from…, on the contrary…)"},"pattern":"S + 不但 + 不 / 没 + A，反而 + B","explain":{"vi":"Kết quả không những không như mong đợi mà còn ngược lại. 反而 là phó từ, đứng sau chủ ngữ của vế sau. Lỗi hay gặp: nhầm 反而 với 反正 (dù sao), hoặc dùng 而且 khi kết quả trái ngược.","en":"The outcome is not only not what was expected but the opposite. 反而 is an adverb placed after the subject of the second clause. Common mistake: confusing 反而 with 反正 (anyway), or using 而且 when the result is the opposite."},"examples":[{"zh":"运动以后，我不但不觉得累，反而更有精神了。","py":"Yùndòng yǐhòu, wǒ búdàn bù juéde lèi, fǎn'ér gèng yǒu jīngshen le.","vi":"Sau khi vận động, tôi không những không thấy mệt mà trái lại còn tỉnh táo hơn.","en":"After exercising I don't feel tired; on the contrary, I have more energy."},{"zh":"降价以后，销售量不但没增加，反而减少了。","py":"Jiàngjià yǐhòu, xiāoshòuliàng búdàn méi zēngjiā, fǎn'ér jiǎnshǎo le.","vi":"Sau khi giảm giá, lượng bán không những không tăng mà trái lại còn giảm.","en":"After the price cut, sales did not rise; they actually fell."}],"quiz":[{"q":"他听了批评，不但没生气，____笑了。","options":["反正","否则","因而","反而"],"answer":3,"explain":{"vi":"不但没…反而…: kết quả trái với dự đoán.","en":"不但没…反而…: the result is the opposite of what was expected."}},{"q":"雨不但没有停，反而____。","options":["慢慢停了","越下越大","没有下","变小了"],"answer":1,"explain":{"vi":"Sau 反而 là điều ngược lại với \"tạnh mưa\".","en":"反而 is followed by the opposite of the rain stopping."}},{"q":"下面哪个句子是正确的？","options":["困难不但吓倒他没有，反而使他更加努力。","困难反而没有吓倒他，不但使他更加努力。","困难不但没有吓倒他，反而使他更加努力。","不但困难没有吓倒他，使他反而更加努力。"],"answer":2,"explain":{"vi":"Trật tự đúng: 不但 + 没有 + A，反而 + B.","en":"The correct order: 不但 + 没有 + A，反而 + B."}},{"q":"“反而”表示：","options":["结果和一般的想法相反","结果和想的一样","不管怎样结果都一样","事情重复发生"],"answer":0,"explain":{"vi":"反而 = trái lại, ngược với lẽ thường.","en":"反而 = contrary to what one would expect."}},{"q":"大家都以为他会失望，他____更有信心了。","options":["反正","何况","反而","凡是"],"answer":2,"explain":{"vi":"Kết quả ngược với điều mọi người nghĩ.","en":"The outcome is the reverse of what everyone thought."}}]},
  {"id":"h5g24","title":{"zh":"固然……但是","vi":"Cố nhiên… nhưng…","en":"固然…但是 (admittedly… but…)"},"pattern":"S + 固然 + Adj / V，但是 / 可是 / 不过 + B","explain":{"vi":"Trước hết thừa nhận A là đúng, sau đó nhấn mạnh B mới là điều quan trọng hơn. 固然 đứng sau chủ ngữ. Lỗi hay gặp: đặt 固然 trước chủ ngữ như 虽然 (固然工资重要 là sai), hoặc nhầm với 果然.","en":"First concedes that A is true, then stresses that B matters more. 固然 goes after the subject. Common mistake: putting 固然 before the subject like 虽然 (固然工资重要 is wrong), or confusing it with 果然."},"examples":[{"zh":"工资固然重要，但发展机会更重要。","py":"Gōngzī gùrán zhòngyào, dàn fāzhǎn jīhuì gèng zhòngyào.","vi":"Lương cố nhiên quan trọng, nhưng cơ hội phát triển còn quan trọng hơn.","en":"Pay matters, of course, but opportunities to grow matter more."},{"zh":"这样做固然省钱，可是会影响质量。","py":"Zhèyàng zuò gùrán shěng qián, kěshì huì yǐngxiǎng zhìliàng.","vi":"Làm thế này cố nhiên tiết kiệm tiền, nhưng sẽ ảnh hưởng đến chất lượng.","en":"Doing it this way does save money, but it will affect quality."}],"quiz":[{"q":"经验____重要，但态度更重要。","options":["果然","固然","居然","忽然"],"answer":1,"explain":{"vi":"Thừa nhận trước rồi chuyển ý: 固然…但….","en":"Concede first, then turn: 固然…但…."}},{"q":"下面哪个句子是正确的？","options":["固然这个方法好，但是成本太高。","这个方法好固然，但是成本太高。","这个方法固然好，所以成本太高。","这个方法固然好，但是成本太高。"],"answer":3,"explain":{"vi":"固然 đứng sau chủ ngữ; vế sau dùng 但是.","en":"固然 follows the subject; the second clause uses 但是."}},{"q":"加班固然能多做一些工作，____长期这样对身体不好。","options":["可是","所以","于是","因而"],"answer":0,"explain":{"vi":"Vế sau của 固然 là ý chuyển: 可是/但是.","en":"After 固然 comes a turn: 可是/但是."}},{"q":"“固然”的作用是：","options":["表示没想到","表示原因","先承认一个事实，再说更重要的另一面","表示事情突然发生"],"answer":2,"explain":{"vi":"固然 = thừa nhận trước, rồi nêu mặt quan trọng hơn.","en":"固然 = concede first, then give the more important side."}},{"q":"钱固然能买到很多东西，但____。","options":["什么都能买到","买不到健康","所以很重要","而且很有用"],"answer":1,"explain":{"vi":"Vế sau phải là ý trái lại, quan trọng hơn.","en":"The second clause must be the contrasting, weightier point."}}]},
  {"id":"h5g25","title":{"zh":"与其说……不如说……","vi":"Nói là A thì chẳng bằng nói là B","en":"与其说…不如说… (not so much A as B)"},"pattern":"与其说 + A，不如说 + B","explain":{"vi":"So sánh hai cách nhận định về cùng một việc và cho rằng B chính xác hơn. Hai vế nên có cấu trúc giống nhau. Lỗi hay gặp: bỏ 说 ở vế sau, hoặc hiểu là chọn giữa hai hành động như 与其…不如.","en":"Compares two ways of describing the same thing and judges B the more accurate. The two halves should be parallel. Common mistake: dropping 说 in the second half, or reading it as a choice between two actions like 与其…不如."},"examples":[{"zh":"与其说他聪明，不如说他比别人更努力。","py":"Yǔqí shuō tā cōngming, bùrú shuō tā bǐ biérén gèng nǔlì.","vi":"Nói anh ấy thông minh thì chẳng bằng nói anh ấy chăm chỉ hơn người khác.","en":"He is not so much clever as harder-working than others."},{"zh":"与其说这是失败，不如说是一次宝贵的经验。","py":"Yǔqí shuō zhè shì shībài, bùrú shuō shì yí cì bǎoguì de jīngyàn.","vi":"Nói đây là thất bại thì chẳng bằng nói là một kinh nghiệm quý báu.","en":"This is less a failure than a valuable experience."}],"quiz":[{"q":"与其说是我教他，____是我们互相学习。","options":["而且说","就是说","不如说","比如说"],"answer":2,"explain":{"vi":"与其说 đi với 不如说.","en":"与其说 pairs with 不如说."}},{"q":"“与其说他是老板，不如说他是朋友”，说话人觉得他更像：","options":["老板","老师","客人","朋友"],"answer":3,"explain":{"vi":"Nhận định sau 不如说 mới là điều người nói cho là đúng hơn.","en":"What follows 不如说 is the description the speaker prefers."}},{"q":"____这是一份工作，不如说这是我的爱好。","options":["与其说","虽然说","听说","据说"],"answer":0,"explain":{"vi":"Vế sau có 不如说 nên vế trước dùng 与其说.","en":"The second half has 不如说, so the first takes 与其说."}},{"q":"下面哪个句子是正确的？","options":["不如说她运气好，与其说她准备得充分。","与其说她运气好，不如说她准备得充分。","与其说她运气好，不如她说准备得充分。","与其她说运气好，不如说她准备得充分。"],"answer":1,"explain":{"vi":"与其说 + A，不如说 + B; chủ ngữ đứng sau 说.","en":"与其说 + A，不如说 + B; the subject comes after 说."}},{"q":"与其说这是批评，不如说是____。","options":["已经结束","批评得对","一种关心","没有听见"],"answer":2,"explain":{"vi":"Hai vế phải cùng loại: 批评 đi với 一种关心.","en":"The halves must match in type: 批评 pairs with 一种关心."}}]},
  {"id":"h5g26","title":{"zh":"不妨","vi":"Phó từ 不妨 (cứ thử… xem)","en":"不妨 (might as well, why not)"},"pattern":"S + 不妨 + V + 一下 / VV / V + O","explain":{"vi":"Dùng để đề nghị một cách lịch sự: làm thế cũng chẳng hại gì, \"cứ thử… xem sao\". Chỉ dùng cho việc chưa làm. Lỗi hay gặp: dùng cho việc đã xảy ra, hoặc nhầm với 不免 (khó tránh khỏi).","en":"Used for a polite suggestion: there is no harm in doing it, \"you might as well\". Only for things not yet done. Common mistake: using it for past events, or confusing it with 不免 (unavoidably)."},"examples":[{"zh":"你不妨先听听大家的意见再做决定。","py":"Nǐ bùfáng xiān tīngting dàjiā de yìjiàn zài zuò juédìng.","vi":"Bạn cứ thử nghe ý kiến mọi người trước rồi hãy quyết định.","en":"You might as well hear everyone's views before deciding."},{"zh":"既然有疑问，不妨直接去问人事部。","py":"Jìrán yǒu yíwèn, bùfáng zhíjiē qù wèn rénshìbù.","vi":"Đã có thắc mắc thì cứ đến hỏi thẳng phòng nhân sự xem.","en":"Since you have doubts, why not ask HR directly?"}],"quiz":[{"q":"这个办法也许有用，你____试一试。","options":["不免","不必","不然","不妨"],"answer":3,"explain":{"vi":"Đề nghị nhẹ nhàng \"cứ thử xem\" dùng 不妨.","en":"A gentle \"why not try\" takes 不妨."}},{"q":"“你不妨直接告诉他”的意思是：","options":["建议你直接告诉他","你不能直接告诉他","你不必告诉他","你已经告诉他了"],"answer":0,"explain":{"vi":"不妨 = đề nghị cứ làm thử.","en":"不妨 = a suggestion to go ahead."}},{"q":"下面哪个句子是正确的？","options":["有时间的话，你去那儿不妨看看了。","有时间的话，不妨你去那儿没看。","有时间的话，你不妨去那儿看看。","昨天你不妨去了那儿看看。"],"answer":2,"explain":{"vi":"不妨 đứng sau chủ ngữ, trước động từ; không dùng cho quá khứ.","en":"不妨 follows the subject and precedes the verb; it is not used for the past."}},{"q":"既然大家意见不同，我们____坐下来好好谈谈。","options":["未免","不妨","难免","以免"],"answer":1,"explain":{"vi":"Đề nghị một cách làm: 不妨.","en":"Suggesting a course of action: 不妨."}},{"q":"“不妨”常常用来：","options":["表示强烈反对","表示后悔","表示命令","客气地提出建议"],"answer":3,"explain":{"vi":"不妨 là cách đề nghị lịch sự.","en":"不妨 is a polite way to make a suggestion."}}]},
  {"id":"h5g27","title":{"zh":"不由得 / 忍不住","vi":"不由得 / 忍不住 (bất giác / không nhịn được)","en":"不由得 / 忍不住 (can't help)"},"pattern":"S + 不由得 + V… | S + 忍不住 + V… | S + 忍不住了","explain":{"vi":"Cả hai chỉ phản ứng không kìm được. 不由得 là phó từ, phải có động từ theo sau. 忍不住 có thể đứng trước động từ hoặc tự làm vị ngữ (我忍不住了). Lỗi hay gặp: nói 我不由得了.","en":"Both mark a reaction one cannot hold back. 不由得 is an adverb and must be followed by a verb. 忍不住 can precede a verb or stand alone as the predicate (我忍不住了). Common mistake: saying 我不由得了."},"examples":[{"zh":"听到这个好消息，她不由得笑了起来。","py":"Tīngdào zhège hǎo xiāoxi, tā bùyóude xiào le qǐlai.","vi":"Nghe tin vui này, cô ấy bất giác bật cười.","en":"Hearing the good news, she couldn't help smiling."},{"zh":"看到满桌的好菜，他忍不住先尝了一口。","py":"Kàndào mǎn zhuō de hǎo cài, tā rěnbuzhù xiān cháng le yì kǒu.","vi":"Thấy bàn đầy món ngon, anh ấy không nhịn được nếm trước một miếng.","en":"Seeing the table full of good food, he couldn't resist having a taste first."}],"quiz":[{"q":"看着孩子们的表演，观众们____鼓起掌来。","options":["不见得","不由得","不得了","不要紧"],"answer":1,"explain":{"vi":"Phản ứng tự nhiên không kìm được: 不由得.","en":"A spontaneous reaction: 不由得."}},{"q":"他讲的笑话太有意思了，我实在____了。","options":["不由得","舍不得","忍不住","恨不得"],"answer":2,"explain":{"vi":"Tự làm vị ngữ (… 了) chỉ có 忍不住.","en":"Only 忍不住 can stand alone as the predicate."}},{"q":"“不由得”的意思是：","options":["自己控制不了地","不允许","不一定","不需要"],"answer":0,"explain":{"vi":"不由得 = bất giác, không tự chủ được.","en":"不由得 = involuntarily."}},{"q":"想起去世的奶奶，她____流下了眼泪。","options":["恨不得","来不及","用不着","忍不住"],"answer":3,"explain":{"vi":"Không kìm được nước mắt: 忍不住.","en":"Unable to hold back tears: 忍不住."}},{"q":"下面哪个句子是正确的？","options":["听了他的故事，我想起了不由得自己的父亲。","听了他的故事，我不由得想起了自己的父亲。","不由得听了他的故事，我想起了自己的父亲。","听了他的故事，我想起了自己的父亲不由得。"],"answer":1,"explain":{"vi":"不由得 đứng sau chủ ngữ, ngay trước động từ.","en":"不由得 follows the subject, right before the verb."}}]},
  {"id":"h5g28","title":{"zh":"恨不得","vi":"恨不得 (chỉ mong sao, hận không thể)","en":"恨不得 (wish one could)"},"pattern":"S + 恨不得 + (马上 / 立刻) + V","explain":{"vi":"Diễn tả mong muốn rất mạnh làm một việc mà thực tế khó hoặc không thể làm được, thường là nói quá. Lỗi hay gặp: hiểu 恨 là \"ghét\"; 恨不得 không có nghĩa ghét, và việc phía sau chưa hề xảy ra.","en":"Expresses a very strong wish to do something that is in fact hard or impossible, often an exaggeration. Common mistake: reading 恨 as \"hate\"; 恨不得 has nothing to do with hating, and what follows has not happened."},"examples":[{"zh":"听说母亲病了，他恨不得马上飞回家。","py":"Tīngshuō mǔqīn bìng le, tā hènbude mǎshàng fēi huí jiā.","vi":"Nghe tin mẹ ốm, anh ấy chỉ mong bay ngay về nhà.","en":"Hearing his mother was ill, he wished he could fly home at once."},{"zh":"她太忙了，恨不得一天有四十八个小时。","py":"Tā tài máng le, hènbude yì tiān yǒu sìshíbā ge xiǎoshí.","vi":"Cô ấy quá bận, chỉ mong một ngày có bốn mươi tám tiếng.","en":"She is so busy she wishes there were forty-eight hours in a day."}],"quiz":[{"q":"“他恨不得马上见到她”的意思是：","options":["他不想见到她","他很讨厌她","他非常想马上见到她","他已经见到她了"],"answer":2,"explain":{"vi":"恨不得 = rất mong muốn.","en":"恨不得 = be dying to."}},{"q":"做错了事，他____找个地方躲起来。","options":["恨不得","舍不得","不见得","怪不得"],"answer":0,"explain":{"vi":"Mong muốn mạnh nhưng khó thực hiện: 恨不得.","en":"A strong but unrealistic wish: 恨不得."}},{"q":"孩子们____明天就放假。","options":["不由得","免不了","来不及","恨不得"],"answer":3,"explain":{"vi":"Rất mong điều chưa xảy ra: 恨不得.","en":"Longing for something not yet real: 恨不得."}},{"q":"“恨不得”后面说的事情常常是：","options":["已经做完的","很想做但实际上做不到的","不愿意做的","每天都做的"],"answer":1,"explain":{"vi":"Sau 恨不得 là điều rất muốn mà chưa hoặc không thể làm.","en":"恨不得 is followed by something much wanted but not (or not yet) possible."}},{"q":"下面哪个句子是正确的？","options":["我恨不得现在就把这个好消息告诉他。","我现在就把这个好消息恨不得告诉他。","恨不得我现在就把这个好消息告诉他。","我现在就把这个好消息告诉他恨不得。"],"answer":0,"explain":{"vi":"恨不得 đứng sau chủ ngữ, trước toàn bộ phần mong muốn.","en":"恨不得 follows the subject and precedes the whole wished-for action."}}]},
  {"id":"h5g29","title":{"zh":"说不定 / 或许","vi":"说不定 / 或许 (biết đâu / có lẽ)","en":"说不定 / 或许 (maybe / perhaps)"},"pattern":"说不定 + clause  /  S + 说不定 + V | S + 或许 + (会 / 能) + V","explain":{"vi":"Cả hai nêu phỏng đoán có thể đúng. 说不定 là khẩu ngữ, đứng trước hoặc sau chủ ngữ, hàm ý \"rất có thể\". 或许 trang trọng hơn, gần với 也许. Lỗi hay gặp: hiểu 说不定 theo từng chữ là \"nói không chắc\" rồi dùng thay cho 不一定 (chưa chắc).","en":"Both give a guess that may well be true. 说不定 is colloquial, goes before or after the subject and leans towards \"quite possibly\". 或许 is more formal, close to 也许. Common mistake: reading 说不定 literally and using it for 不一定 (not necessarily)."},"examples":[{"zh":"你再等一会儿，说不定他马上就到了。","py":"Nǐ zài děng yíhuìr, shuōbudìng tā mǎshàng jiù dào le.","vi":"Bạn đợi thêm chút nữa, biết đâu anh ấy sắp đến rồi.","en":"Wait a little longer; he may well be here any minute."},{"zh":"换一种方法，或许能解决这个问题。","py":"Huàn yì zhǒng fāngfǎ, huòxǔ néng jiějué zhège wèntí.","vi":"Đổi một cách khác, có lẽ sẽ giải quyết được vấn đề này.","en":"With a different method, perhaps this problem can be solved."}],"quiz":[{"q":"“他说不定已经走了”的意思是：","options":["他一定没走","他不能走","他可能已经走了","他说他不走"],"answer":2,"explain":{"vi":"说不定 = có thể, biết đâu.","en":"说不定 = possibly, may well."}},{"q":"别着急，____明天就有好消息了。","options":["说不定","恨不得","不由得","舍不得"],"answer":0,"explain":{"vi":"Phỏng đoán lạc quan \"biết đâu\" dùng 说不定.","en":"A hopeful \"who knows\" takes 说不定."}},{"q":"多和同事交流，____会有新的想法。","options":["何必","未免","毕竟","或许"],"answer":3,"explain":{"vi":"Phỏng đoán \"có lẽ\" dùng 或许.","en":"A guess, \"perhaps\", takes 或许."}},{"q":"下面哪个词的意思和“或许”最接近？","options":["必然","也许","居然","固然"],"answer":1,"explain":{"vi":"或许 ≈ 也许 (có lẽ).","en":"或许 ≈ 也许 (perhaps)."}},{"q":"下面哪个句子是正确的？","options":["你去问问他，他知道说不定了。","你说不定去问问他，他知道。","你去问问他，他说不知道定。","你去问问他，说不定他知道。"],"answer":3,"explain":{"vi":"说不定 đứng đầu vế phỏng đoán.","en":"说不定 opens the clause that holds the guess."}}]},
  {"id":"h5g30","title":{"zh":"舍不得 / 用不着","vi":"舍不得 (không nỡ, tiếc) / 用不着 (không cần)","en":"舍不得 / 用不着 (hate to part with / no need to)"},"pattern":"S + 舍不得 + V / N | (S) + 用不着 + V / N","explain":{"vi":"舍不得: không nỡ rời xa, hoặc tiếc không dám dùng, không dám tiêu. 用不着: không cần thiết phải làm. Lỗi hay gặp: hiểu 用不着 là \"không dùng được\"; nghĩa thường gặp của nó là \"không cần\".","en":"舍不得: unwilling to part with something, or too thrifty to use or spend. 用不着: there is no need to. Common mistake: reading 用不着 as \"cannot be used\"; its usual meaning is \"no need\"."},"examples":[{"zh":"这件衣服太贵了，我一直舍不得穿。","py":"Zhè jiàn yīfu tài guì le, wǒ yìzhí shěbude chuān.","vi":"Cái áo này đắt quá nên tôi cứ tiếc mãi không dám mặc.","en":"This dress was so expensive that I can never bring myself to wear it."},{"zh":"这点儿小事用不着麻烦经理。","py":"Zhè diǎnr xiǎoshì yòngbuzháo máfan jīnglǐ.","vi":"Chuyện nhỏ này không cần phải làm phiền giám đốc.","en":"There is no need to trouble the manager over such a small matter."}],"quiz":[{"q":"这么近的路，____打车，走过去就行了。","options":["忍不住","恨不得","不由得","用不着"],"answer":3,"explain":{"vi":"Không cần thiết phải làm: 用不着.","en":"No need to do it: 用不着."}},{"q":"要离开工作了五年的公司，她真有点儿____。","options":["用不着","舍不得","说不定","恨不得"],"answer":1,"explain":{"vi":"Không nỡ rời xa: 舍不得.","en":"Reluctant to leave: 舍不得."}},{"q":"“你用不着担心”的意思是：","options":["你不需要担心","你不能担心","你不会担心","你担心也没用"],"answer":0,"explain":{"vi":"用不着 = không cần.","en":"用不着 = need not."}},{"q":"他平时很节约，连一杯咖啡都____买。","options":["来得及","说不定","舍不得","不由得"],"answer":2,"explain":{"vi":"Tiếc tiền không dám mua: 舍不得.","en":"Too thrifty to buy it: 舍不得."}},{"q":"下面哪个句子是正确的？","options":["妈妈舍把旧家具不得扔掉。","妈妈舍不得把旧家具扔掉。","妈妈舍不把旧家具得扔掉。","妈妈舍不得旧家具把扔掉。"],"answer":1,"explain":{"vi":"舍不得 đứng trước cả cụm 把….","en":"舍不得 goes before the whole 把 phrase."}}]},
  {"id":"h5g31","title":{"zh":"显得","vi":"Động từ 显得 (tỏ ra, trông có vẻ)","en":"显得 (appear, look)"},"pattern":"S + 显得 + (很 / 更 / 特别 / 有点儿) + Adj | S + 显得 + 有 / 没有 + N","explain":{"vi":"Nói một đặc điểm lộ ra bên ngoài, người khác nhìn vào thấy như thế. Sau 显得 phải là tính từ hoặc cụm miêu tả, thường có phó từ chỉ mức độ. Lỗi hay gặp: đặt danh từ ngay sau 显得 (显得一个经理 là sai), hoặc nhầm với 显示 (cho thấy).","en":"Says that a quality shows on the outside, as others perceive it. 显得 must be followed by an adjective or descriptive phrase, usually with a degree adverb. Common mistake: putting a noun right after it (显得一个经理 is wrong), or confusing it with 显示 (to show)."},"examples":[{"zh":"穿上这件衬衫，他显得特别精神。","py":"Chuān shang zhè jiàn chènshān, tā xiǎnde tèbié jīngshen.","vi":"Mặc chiếc sơ mi này vào, anh ấy trông đặc biệt tươi tỉnh.","en":"In this shirt he looks particularly smart."},{"zh":"第一次在会上发言，她显得有点儿紧张。","py":"Dì yī cì zài huì shang fāyán, tā xiǎnde yǒudiǎnr jǐnzhāng.","vi":"Lần đầu phát biểu trong cuộc họp, cô ấy tỏ ra hơi căng thẳng.","en":"Speaking at a meeting for the first time, she seemed a little nervous."}],"quiz":[{"q":"刷了墙以后，办公室____亮多了。","options":["表现","显示","显得","表示"],"answer":2,"explain":{"vi":"显得 + tính từ: trông có vẻ….","en":"显得 + adjective: looks …."}},{"q":"和年轻人在一起，他____更有活力了。","options":["显得","显示","表明","说明"],"answer":0,"explain":{"vi":"显得 + 有 + danh từ: tỏ ra có….","en":"显得 + 有 + noun: appears to have …."}},{"q":"下面哪个句子是正确的？","options":["她今天很高兴显得。","她显得今天高兴很。","显得她今天很高兴。","她今天显得很高兴。"],"answer":3,"explain":{"vi":"显得 đứng sau chủ ngữ, trước \"很 + tính từ\".","en":"显得 follows the subject and precedes \"很 + adjective\"."}},{"q":"“他显得很累”的意思是：","options":["他一定不累","他看起来很累","他说自己很累","他让别人很累"],"answer":1,"explain":{"vi":"显得 = trông có vẻ.","en":"显得 = looks, appears."}},{"q":"他话不多，在新同事面前显得____。","options":["一个经理","去吃饭了","有些害羞","三年时间"],"answer":2,"explain":{"vi":"Sau 显得 là cụm tính từ.","en":"显得 takes an adjective phrase."}}]},
  {"id":"h5g32","title":{"zh":"值得","vi":"值得 (đáng, xứng đáng)","en":"值得 (be worth)"},"pattern":"S (thing) + (很) + 值得 + V | S + 值得 + person + V | …(很 / 不) 值得","explain":{"vi":"Nói một việc có giá trị, đáng để làm. Chủ ngữ thường là sự vật, động từ phía sau mang nghĩa bị động nhưng không dùng 被. Phủ định: 不值得. Lỗi hay gặp: thêm 被 (这部电影值得被看 là sai).","en":"Says that something has value and is worth doing. The subject is usually the thing, and the verb after it is passive in sense but takes no 被. Negative: 不值得. Common mistake: adding 被 (这部电影值得被看 is wrong)."},"examples":[{"zh":"这本书写得很好，值得认真读一读。","py":"Zhè běn shū xiě de hěn hǎo, zhíde rènzhēn dú yi dú.","vi":"Cuốn sách này viết rất hay, đáng để đọc kỹ.","en":"This book is well written and worth reading carefully."},{"zh":"为这点儿小事生气，实在不值得。","py":"Wèi zhè diǎnr xiǎoshì shēngqì, shízài bù zhíde.","vi":"Tức giận vì chuyện nhỏ này thật sự không đáng.","en":"Getting angry over such a small thing really isn't worth it."}],"quiz":[{"q":"这个问题____我们认真考虑。","options":["显得","值得","舍得","懂得"],"answer":1,"explain":{"vi":"值得 + người + động từ: đáng để ai làm gì.","en":"值得 + person + verb: worth someone's doing."}},{"q":"下面哪个句子是正确的？","options":["这部电影很值得看。","这部电影很值得被看。","这部电影看很值得了。","很值得这部电影看。"],"answer":0,"explain":{"vi":"值得 + động từ, không dùng 被.","en":"值得 + verb, with no 被."}},{"q":"为了省十块钱排一个小时的队，____。","options":["不由得","不见得","恨不得","不值得"],"answer":3,"explain":{"vi":"Không đáng: 不值得.","en":"Not worth it: 不值得."}},{"q":"他认真负责的态度值得我们____。","options":["学习了","被学习","学习","学习着"],"answer":2,"explain":{"vi":"Sau 值得 là động từ nguyên dạng.","en":"值得 takes a bare verb."}},{"q":"“那个地方值得一去”的意思是：","options":["那个地方很贵","去那个地方是有价值的","那个地方只能去一次","那个地方不用去"],"answer":1,"explain":{"vi":"值得一去 = đáng để đi một lần.","en":"值得一去 = worth a visit."}}]},
  {"id":"h5g33","title":{"zh":"对……而言 / 就……来说 / 在……看来","vi":"Ba khung nêu góc nhìn","en":"对…而言 / 就…来说 / 在…看来 (for / as regards / in the view of)"},"pattern":"对 + N + 而言，… (formal 对…来说) | 就 + aspect + 来说 / 而言，… | 在 + person + 看来，…","explain":{"vi":"对…而言: xét từ phía ai, điều gì ảnh hưởng đến họ. 就…来说: xét riêng về một mặt nào đó. 在…看来: theo cách nhìn, ý kiến của ai. Lỗi hay gặp: ghép lẫn các khung (对我看来, 在我而言 đều sai).","en":"对…而言: from the standpoint of whoever is affected. 就…来说: looking at one particular aspect. 在…看来: in someone's opinion. Common mistake: mixing the frames (对我看来 and 在我而言 are both wrong)."},"examples":[{"zh":"对公司而言，人才是最宝贵的资源。","py":"Duì gōngsī ér yán, réncái shì zuì bǎoguì de zīyuán.","vi":"Đối với công ty, nhân tài là nguồn lực quý giá nhất.","en":"For a company, talented people are the most valuable resource."},{"zh":"在我看来，这个方案还有改进的空间。","py":"Zài wǒ kànlái, zhège fāng'àn hái yǒu gǎijìn de kōngjiān.","vi":"Theo tôi, phương án này vẫn còn chỗ có thể cải tiến.","en":"In my view, this proposal still has room for improvement."}],"quiz":[{"q":"____我看来，这件事并不复杂。","options":["对","向","把","在"],"answer":3,"explain":{"vi":"在…看来: theo ý ai.","en":"在…看来: in someone's view."}},{"q":"对年轻人____，积累经验比收入更重要。","options":["而言","看来","以来","之间"],"answer":0,"explain":{"vi":"对…而言 = 对…来说 (đối với… mà nói).","en":"对…而言 = 对…来说 (as far as … is concerned)."}},{"q":"____工作经验来说，他比其他应聘者更有优势。","options":["被","就","向","把"],"answer":1,"explain":{"vi":"就…来说: xét về mặt….","en":"就…来说: as far as … is concerned."}},{"q":"下面哪个句子是正确的？","options":["对老师看来，他是最努力的学生。","在老师而言，他是最努力的学生。","在老师看来，他是最努力的学生。","就老师看来说，他是最努力的学生。"],"answer":2,"explain":{"vi":"Khung đúng là 在 + người + 看来.","en":"The correct frame is 在 + person + 看来."}},{"q":"“在他看来，这样做没有必要”的意思是：","options":["他认为没有必要这样做","他看见了这样做","他没来看","别人认为他没有必要"],"answer":0,"explain":{"vi":"在他看来 = theo ý anh ấy.","en":"在他看来 = in his opinion."}}]},
  {"id":"h5g34","title":{"zh":"逐渐 / 逐步","vi":"逐渐 (dần dần) / 逐步 (từng bước)","en":"逐渐 / 逐步 (gradually / step by step)"},"pattern":"S + 逐渐 + V / Adj (natural, gradual change) | S + 逐步 + V (planned, in stages)","explain":{"vi":"逐渐: thay đổi từ từ một cách tự nhiên, đứng trước động từ hoặc tính từ. 逐步: tiến hành có kế hoạch, từng bước một, chỉ đứng trước động từ. Lỗi hay gặp: dùng 逐步 trước tính từ (天气逐步冷了 là sai).","en":"逐渐: a slow, natural change; it goes before a verb or an adjective. 逐步: planned progress in stages; only before a verb. Common mistake: using 逐步 before an adjective (天气逐步冷了 is wrong)."},"examples":[{"zh":"天气逐渐变暖，公园里的人多了起来。","py":"Tiānqì zhújiàn biàn nuǎn, gōngyuán lǐ de rén duō le qǐlai.","vi":"Thời tiết dần ấm lên, người trong công viên cũng đông hơn.","en":"As the weather gradually warms up, more people are in the park."},{"zh":"公司计划逐步提高员工的工资。","py":"Gōngsī jìhuà zhúbù tígāo yuángōng de gōngzī.","vi":"Công ty có kế hoạch từng bước nâng lương cho nhân viên.","en":"The company plans to raise staff pay step by step."}],"quiz":[{"q":"秋天到了，天气____凉了。","options":["逐步","逐渐","陆续","纷纷"],"answer":1,"explain":{"vi":"Trước tính từ (凉), thay đổi tự nhiên, dùng 逐渐.","en":"Before an adjective (凉), for natural change, use 逐渐."}},{"q":"我们要有计划地、____地解决这些问题。","options":["陆续","纷纷","一再","逐步"],"answer":3,"explain":{"vi":"Làm có kế hoạch, từng bước: 逐步.","en":"Planned and in stages: 逐步."}},{"q":"来了半年以后，他____习惯了这里的生活。","options":["逐渐","一律","纷纷","再三"],"answer":0,"explain":{"vi":"Quen dần một cách tự nhiên: 逐渐.","en":"Getting used to something naturally: 逐渐."}},{"q":"“逐步”和“逐渐”，哪个后面不能直接用形容词？","options":["只有“逐渐”不能","两个都能","只有“逐步”不能","两个都不能"],"answer":2,"explain":{"vi":"逐步 chỉ đứng trước động từ.","en":"逐步 goes only before verbs."}},{"q":"随着经验的增加，她也____变得自信了。","options":["曾经","逐渐","分别","照常"],"answer":1,"explain":{"vi":"Thay đổi từ từ theo thời gian: 逐渐.","en":"A slow change over time: 逐渐."}}]},
  {"id":"h5g35","title":{"zh":"陆续 / 纷纷","vi":"陆续 (lần lượt) / 纷纷 (ùn ùn, đua nhau)","en":"陆续 / 纷纷 (one after another / in great numbers)"},"pattern":"S (plural) + 陆续 + V | S (plural) + 纷纷 + V","explain":{"vi":"陆续: nhiều người/vật lần lượt, trước sau nối nhau. 纷纷: nhiều người cùng làm một việc gần như cùng lúc, dồn dập. Chủ ngữ phải là số nhiều. Lỗi hay gặp: dùng với chủ ngữ là một người làm một việc (他一个人纷纷举手 là sai).","en":"陆续: many people or things, one after another with gaps. 纷纷: many people doing the same thing almost at once, in a rush. The subject must be plural. Common mistake: using them with one person doing one thing (他一个人纷纷举手 is wrong)."},"examples":[{"zh":"八点以后，参加会议的人陆续到了。","py":"Bā diǎn yǐhòu, cānjiā huìyì de rén lùxù dào le.","vi":"Sau tám giờ, những người dự họp lần lượt đến.","en":"After eight o'clock, the people attending the meeting arrived one after another."},{"zh":"听到这个消息，大家纷纷表示祝贺。","py":"Tīngdào zhège xiāoxi, dàjiā fēnfēn biǎoshì zhùhè.","vi":"Nghe tin này, mọi người đua nhau chúc mừng.","en":"On hearing the news, everyone offered their congratulations."}],"quiz":[{"q":"新产品上市后，顾客们____打电话来咨询。","options":["逐步","毕竟","未必","纷纷"],"answer":3,"explain":{"vi":"Nhiều người cùng làm một việc dồn dập: 纷纷.","en":"Many people doing the same thing in a rush: 纷纷."}},{"q":"春天来了，各种花____开了。","options":["一律","陆续","反正","再三"],"answer":1,"explain":{"vi":"Trước sau nối nhau: 陆续.","en":"One after another: 陆续."}},{"q":"“客人们陆续离开了”的意思是：","options":["客人们一个接一个地离开了","客人们一起离开了","只有一位客人离开了","客人们都不想离开"],"answer":0,"explain":{"vi":"陆续 = lần lượt.","en":"陆续 = in succession."}},{"q":"下面哪个句子是正确的？","options":["他一个人纷纷举手回答问题。","同学们举手回答问题纷纷。","同学们纷纷举手回答问题。","纷纷同学们举手回答问题。"],"answer":2,"explain":{"vi":"纷纷 cần chủ ngữ số nhiều và đứng trước động từ.","en":"纷纷 needs a plural subject and goes before the verb."}},{"q":"这几年，我的大学同学____结了婚。","options":["逐步","陆续","一再","照常"],"answer":1,"explain":{"vi":"Nhiều người lần lượt kết hôn: 陆续.","en":"Many people marrying one after another: 陆续."}}]},
  {"id":"h5g36","title":{"zh":"一再 / 再三","vi":"一再 / 再三 (hết lần này đến lần khác)","en":"一再 / 再三 (again and again)"},"pattern":"S + 一再 + V | S + 再三 + V (考虑 / 强调 / 要求 / 提醒 / 解释) | V + 再三 (考虑再三)","explain":{"vi":"Cả hai chỉ việc lặp lại nhiều lần. 一再 dùng rộng, kể cả việc không cố ý (一再迟到, 一再上涨). 再三 chỉ đi với hành động có chủ ý như nói, nghĩ, yêu cầu, và có thể đứng sau động từ (考虑再三). Lỗi hay gặp: dùng 再三 cho việc không chủ ý (价格再三上涨 là sai).","en":"Both mark many repetitions. 一再 is general and covers unintended events (一再迟到, 一再上涨). 再三 goes only with deliberate acts such as saying, thinking or requesting, and may follow the verb (考虑再三). Common mistake: using 再三 for something not deliberate (价格再三上涨 is wrong)."},"examples":[{"zh":"他一再迟到，经理已经批评他好几次了。","py":"Tā yízài chídào, jīnglǐ yǐjīng pīpíng tā hǎo jǐ cì le.","vi":"Anh ấy hết lần này đến lần khác đến muộn, giám đốc đã phê bình mấy lần rồi.","en":"He keeps coming late, and the manager has already criticised him several times."},{"zh":"经过再三考虑，她决定接受这份工作。","py":"Jīngguò zàisān kǎolǜ, tā juédìng jiēshòu zhè fèn gōngzuò.","vi":"Sau khi cân nhắc nhiều lần, cô ấy quyết định nhận công việc này.","en":"After thinking it over again and again, she decided to accept the job."}],"quiz":[{"q":"妈妈____提醒我出门要带钥匙。","options":["再三","逐渐","陆续","纷纷"],"answer":0,"explain":{"vi":"Nhắc đi nhắc lại nhiều lần: 再三.","en":"Reminding over and over: 再三."}},{"q":"考虑____，我还是决定留在现在的公司。","options":["一再","陆续","逐步","再三"],"answer":3,"explain":{"vi":"Chỉ 再三 đứng được sau động từ: 考虑再三.","en":"Only 再三 can follow the verb: 考虑再三."}},{"q":"“他一再表示感谢”的意思是：","options":["他只表示了一次感谢","他表示了很多次感谢","他再也不感谢了","他第三次表示感谢"],"answer":1,"explain":{"vi":"一再 = nhiều lần.","en":"一再 = many times."}},{"q":"价格____上涨，很多人买不起房子了。","options":["再三","各自","一再","分别"],"answer":2,"explain":{"vi":"Việc không do chủ ý (giá tăng) dùng 一再, không dùng 再三.","en":"Something not deliberate (prices rising) takes 一再, not 再三."}},{"q":"下面哪个句子是正确的？","options":["老师强调了再三考试的时间。","再三老师强调了考试的时间。","老师再三强调了考试的时间。","老师强调了考试的时间再三。"],"answer":2,"explain":{"vi":"再三 đứng sau chủ ngữ, trước động từ.","en":"再三 follows the subject and precedes the verb."}}]},
  {"id":"h5g37","title":{"zh":"依然 / 照常","vi":"依然 (vẫn như xưa) / 照常 (như thường lệ)","en":"依然 / 照常 (still / as usual)"},"pattern":"S + 依然 + V / Adj | S + 照常 + V (上班 / 营业 / 进行 / 举行)","explain":{"vi":"依然: trạng thái vẫn như trước, không đổi; là cách nói trang trọng của 仍然. 照常: hoạt động vẫn diễn ra như mọi khi dù có tình huống đặc biệt; chỉ đi với động từ chỉ hoạt động. Lỗi hay gặp: dùng 照常 trước tính từ (照常漂亮 là sai).","en":"依然: a state remains as it was; the formal counterpart of 仍然. 照常: an activity goes on as usual despite special circumstances; only with activity verbs. Common mistake: using 照常 before an adjective (照常漂亮 is wrong)."},"examples":[{"zh":"十年过去了，这里的风景依然那么美。","py":"Shí nián guòqù le, zhèlǐ de fēngjǐng yīrán nàme měi.","vi":"Mười năm trôi qua, phong cảnh nơi đây vẫn đẹp như thế.","en":"Ten years on, the scenery here is still just as beautiful."},{"zh":"春节期间，这家超市照常营业。","py":"Chūnjié qījiān, zhè jiā chāoshì zhàocháng yíngyè.","vi":"Trong dịp Tết, siêu thị này vẫn mở cửa như thường.","en":"During the Spring Festival, this supermarket is open as usual."}],"quiz":[{"q":"虽然下着大雨，比赛____进行。","options":["逐渐","陆续","照常","纷纷"],"answer":2,"explain":{"vi":"Hoạt động vẫn diễn ra như thường: 照常.","en":"The activity goes ahead as usual: 照常."}},{"q":"多年不见，她____那么年轻。","options":["照常","依然","陆续","一再"],"answer":1,"explain":{"vi":"Trạng thái không đổi, đứng trước tính từ: 依然.","en":"An unchanged state, before an adjective: 依然."}},{"q":"“明天公司照常上班”的意思是：","options":["明天不上班","明天提前上班","明天经常上班","明天和平时一样上班"],"answer":3,"explain":{"vi":"照常 = như thường lệ.","en":"照常 = as usual."}},{"q":"下面哪个句子是正确的？","options":["尽管遇到很多困难，他依然没有放弃。","尽管遇到很多困难，他没有依然放弃。","尽管遇到很多困难，依然他没有放弃。","尽管遇到很多困难，他没有放弃依然。"],"answer":0,"explain":{"vi":"依然 đứng sau chủ ngữ, trước 没有.","en":"依然 follows the subject and precedes 没有."}},{"q":"“依然”的意思和下面哪个词最接近？","options":["忽然","居然","仍然","固然"],"answer":2,"explain":{"vi":"依然 ≈ 仍然 (vẫn).","en":"依然 ≈ 仍然 (still)."}}]},
  {"id":"h5g38","title":{"zh":"分别 / 各自 / 彼此","vi":"分别 / 各自 / 彼此 (lần lượt riêng / mỗi người tự / lẫn nhau)","en":"分别 / 各自 / 彼此 (separately / each / each other)"},"pattern":"S + 分别 + V (separately; respectively) | S (plural) + 各自 + V  /  各自 + 的 + N | 彼此 + V  /  彼此 + 的 + N  /  彼此之间","explain":{"vi":"分别: làm riêng với từng đối tượng, hoặc \"lần lượt là\". 各自: mỗi người tự mình, mỗi bên riêng. 彼此: hai bên với nhau, gần nghĩa 互相 nhưng là đại từ nên có thể làm định ngữ (彼此的看法). Lỗi hay gặp: dùng 各自 với nghĩa \"lẫn nhau\".","en":"分别: dealing with each one separately, or \"respectively\". 各自: each on their own, each side its own. 彼此: both sides towards each other, close to 互相 but a pronoun, so it can modify a noun (彼此的看法). Common mistake: using 各自 for \"each other\"."},"examples":[{"zh":"会议结束后，大家各自回到了办公室。","py":"Huìyì jiéshù hòu, dàjiā gèzì huídào le bàngōngshì.","vi":"Sau khi cuộc họp kết thúc, mọi người ai về văn phòng người nấy.","en":"After the meeting, everyone went back to their own offices."},{"zh":"我们认识多年，彼此非常了解。","py":"Wǒmen rènshi duō nián, bǐcǐ fēicháng liǎojiě.","vi":"Chúng tôi quen nhau nhiều năm, rất hiểu nhau.","en":"We have known each other for years and understand each other very well."}],"quiz":[{"q":"经理____和每一位新员工谈了话。","options":["彼此","各自","互相","分别"],"answer":3,"explain":{"vi":"Làm riêng với từng người: 分别.","en":"Doing it with each person separately: 分别."}},{"q":"朋友之间应该____信任。","options":["彼此","各自","分别","陆续"],"answer":0,"explain":{"vi":"Hai bên đối với nhau: 彼此.","en":"Both sides towards each other: 彼此."}},{"q":"下班以后，同事们____回家了。","options":["彼此","各自","互相","一再"],"answer":1,"explain":{"vi":"Mỗi người tự về nhà mình: 各自.","en":"Each going to their own home: 各自."}},{"q":"小王和小李____来自北京和上海。","options":["彼此","互相","分别","陆续"],"answer":2,"explain":{"vi":"\"Lần lượt là\" dùng 分别.","en":"\"Respectively\" takes 分别."}},{"q":"“彼此”的意思是：","options":["每个人自己","你和我、双方","一个接一个","和平时一样"],"answer":1,"explain":{"vi":"彼此 = hai bên với nhau.","en":"彼此 = each other, both sides."}}]},
  {"id":"h5g39","title":{"zh":"似乎 / 仿佛 / ……似的","vi":"似乎 / 仿佛 / …似的 (dường như / tựa như / như thể)","en":"似乎 / 仿佛 / …似的 (seem / as if)"},"pattern":"S + 似乎 + V / Adj (uncertain judgement) | 仿佛 + clause (as if; simile) | (像 / 好像 / 仿佛) + … + 似的","explain":{"vi":"似乎: phán đoán chưa chắc chắn, trang trọng hơn 好像. 仿佛: so sánh ví von \"tựa như\", văn viết. 似的 (shìde) đứng cuối cụm so sánh, thường đi với 像/好像/仿佛. Lỗi hay gặp: viết nhầm 似的 thành 是的, hoặc đặt 似的 ở đầu cụm.","en":"似乎: an uncertain judgement, more formal than 好像. 仿佛: a simile, \"as if\", written style. 似的 (shìde) ends the comparison phrase, usually with 像/好像/仿佛. Common mistake: writing 是的 for 似的, or putting 似的 at the front."},"examples":[{"zh":"他似乎对这个结果不太满意。","py":"Tā sìhū duì zhège jiéguǒ bú tài mǎnyì.","vi":"Anh ấy dường như không hài lòng lắm với kết quả này.","en":"He seems not very satisfied with this result."},{"zh":"她高兴得像个孩子似的。","py":"Tā gāoxìng de xiàng ge háizi shìde.","vi":"Cô ấy vui như một đứa trẻ vậy.","en":"She is as happy as a child."}],"quiz":[{"q":"他今天一句话也不说，____有什么心事。","options":["似的","固然","似乎","毕竟"],"answer":2,"explain":{"vi":"Phán đoán chưa chắc chắn: 似乎.","en":"An uncertain judgement: 似乎."}},{"q":"她跑得飞快，像一阵风____。","options":["似的","似乎","仿佛","好像"],"answer":0,"explain":{"vi":"像…似的: 似的 đứng cuối.","en":"像…似的: 似的 comes at the end."}},{"q":"走进这家老店，____回到了三十年前。","options":["似的","何必","未免","仿佛"],"answer":3,"explain":{"vi":"So sánh ví von đứng đầu vế: 仿佛.","en":"A simile opening the clause: 仿佛."}},{"q":"下面哪个句子是正确的？","options":["他似的好像什么都不知道。","他好像什么都不知道似的。","他好像似的什么都不知道。","似的他好像什么都不知道。"],"answer":1,"explain":{"vi":"好像…似的: 似的 đứng cuối câu.","en":"好像…似的: 似的 ends the sentence."}},{"q":"“似乎”表示：","options":["完全肯定","强烈的希望","不太肯定的判断","客气的建议"],"answer":2,"explain":{"vi":"似乎 = dường như.","en":"似乎 = it seems."}}]},
  {"id":"h5g40","title":{"zh":"极其 / 格外 / 过于","vi":"Phó từ mức độ 极其 / 格外 / 过于","en":"极其 / 格外 / 过于 (extremely / especially / excessively)"},"pattern":"极其 + Adj / V (two syllables) | 格外 + Adj / V | 过于 + Adj / V","explain":{"vi":"极其: mức độ rất cao, văn viết, đứng trước tính từ hai âm tiết. 格外: hơn hẳn mức bình thường trong một hoàn cảnh nào đó. 过于: quá mức cần thiết, mang ý phê bình. Lỗi hay gặp: đặt 极其 sau tính từ như 极了 (重要极其 là sai).","en":"极其: a very high degree, written, before two-syllable adjectives. 格外: more than usual in a particular situation. 过于: beyond what is appropriate, with a critical note. Common mistake: placing 极其 after the adjective like 极了 (重要极其 is wrong)."},"examples":[{"zh":"这次谈判对公司来说极其重要。","py":"Zhè cì tánpàn duì gōngsī lái shuō jíqí zhòngyào.","vi":"Cuộc đàm phán lần này cực kỳ quan trọng đối với công ty.","en":"This negotiation is extremely important for the company."},{"zh":"雨后的空气格外新鲜。","py":"Yǔ hòu de kōngqì géwài xīnxiān.","vi":"Không khí sau cơn mưa đặc biệt trong lành.","en":"The air after rain is especially fresh."}],"quiz":[{"q":"你对自己的要求____严格了，应该放松一点儿。","options":["极其","过于","陆续","依然"],"answer":1,"explain":{"vi":"Quá mức, có ý phê bình: 过于…了.","en":"Too much, with criticism: 过于…了."}},{"q":"今天是她的生日，她打扮得____漂亮。","options":["未免","何必","逐步","格外"],"answer":3,"explain":{"vi":"Hơn hẳn ngày thường trong dịp đặc biệt: 格外.","en":"More than usual on a special day: 格外."}},{"q":"下面哪个句子是正确的？","options":["这个问题极其复杂。","这个问题复杂极其。","这个问题极其复杂极了。","极其这个问题复杂。"],"answer":0,"explain":{"vi":"极其 đứng trước tính từ, không đứng sau.","en":"极其 goes before the adjective, never after."}},{"q":"“过于”常常表示：","options":["和平时一样","程度很低","超过了合适的程度","越来越好"],"answer":2,"explain":{"vi":"过于 = quá mức.","en":"过于 = excessively."}},{"q":"节日的晚上，街上____热闹。","options":["各自","格外","分别","一再"],"answer":1,"explain":{"vi":"Hơn hẳn bình thường: 格外.","en":"More than on ordinary days: 格外."}}]},
  {"id":"h5g41","title":{"zh":"动词 + 来 + 动词 + 去","vi":"Động từ + 来 + động từ + 去","en":"V来V去 (over and over, back and forth)"},"pattern":"V + 来 + V + 去，+ result / comment | 走 / 跑 / 飞 + 来 + V + 去 (back and forth)","explain":{"vi":"Chỉ hành động lặp đi lặp lại hoặc qua lại nhiều lần; phía sau thường là kết quả (想来想去，还是…). Lỗi hay gặp: đặt tân ngữ ngay sau cụm này (看来看去这几件衣服 là sai); tân ngữ phải đưa lên trước.","en":"Marks an action repeated many times or movement to and fro; a result usually follows (想来想去，还是…). Common mistake: putting the object right after the phrase (看来看去这几件衣服 is wrong); the object moves to the front."},"examples":[{"zh":"我想来想去，还是觉得第一个方案最好。","py":"Wǒ xiǎng lái xiǎng qù, háishi juéde dì yī ge fāng'àn zuì hǎo.","vi":"Tôi nghĩ đi nghĩ lại, vẫn thấy phương án đầu tiên là tốt nhất.","en":"I thought it over and over and still feel the first proposal is best."},{"zh":"他在办公室里走来走去，好像有什么急事。","py":"Tā zài bàngōngshì lǐ zǒu lái zǒu qù, hǎoxiàng yǒu shénme jíshì.","vi":"Anh ấy đi đi lại lại trong văn phòng, hình như có việc gì gấp.","en":"He is pacing up and down the office as if something urgent has come up."}],"quiz":[{"q":"我找____，也没找到那把钥匙。","options":["去找来","来来去去","着找着","来找去"],"answer":3,"explain":{"vi":"Cấu trúc: V + 来 + V + 去.","en":"Pattern: V + 来 + V + 去."}},{"q":"下面哪个句子是正确的？","options":["我看来看去这几件衣服，都不太满意。","这几件衣服我看来看去，都不太满意。","我看这几件衣服来看去，都不太满意。","我看来这几件衣服看去，都不太满意。"],"answer":1,"explain":{"vi":"Tân ngữ đứng trước, không đứng sau V来V去.","en":"The object goes in front, not after V来V去."}},{"q":"“商量来商量去”的意思是：","options":["商量了很多次","来这儿商量，再去那儿商量","刚开始商量","不想商量"],"answer":0,"explain":{"vi":"V来V去 = làm đi làm lại nhiều lần.","en":"V来V去 = doing it many times over."}},{"q":"孩子们在院子里跑____跑去，玩儿得很开心。","options":["去","着","来","过"],"answer":2,"explain":{"vi":"跑来跑去: chạy qua chạy lại.","en":"跑来跑去: run back and forth."}},{"q":"大家讨论来讨论去，____。","options":["明天开始讨论","最后还是没有结果","从来不讨论","讨论室在三楼"],"answer":1,"explain":{"vi":"Sau V来V去 thường là kết quả.","en":"V来V去 is usually followed by the outcome."}}]},
  {"id":"h5g42","title":{"zh":"使 / 令（使令句）","vi":"Câu cầu khiến với 使 / 令","en":"使 / 令 (causatives: make, cause)"},"pattern":"A + 使 / 令 + person / thing + feeling / change | 令人 + Adj (令人满意 / 失望 / 感动)","explain":{"vi":"使 và 令 dùng trong văn viết để nói A gây ra một cảm xúc hay thay đổi ở B. 令 chủ yếu đi với cảm xúc (令人失望). Lỗi hay gặp: dùng 使/令 với nghĩa \"bảo, sai ai làm việc gì\" (经理使我去银行 là sai, phải dùng 让/叫); sau 使/令 không thêm 了.","en":"使 and 令 are written-style words saying that A causes a feeling or change in B. 令 mostly goes with feelings (令人失望). Common mistake: using 使/令 for \"tell someone to do something\" (经理使我去银行 is wrong; use 让/叫); no 了 after 使/令."},"examples":[{"zh":"这个结果令所有人都感到意外。","py":"Zhège jiéguǒ lìng suǒyǒu rén dōu gǎndào yìwài.","vi":"Kết quả này khiến tất cả mọi người đều cảm thấy bất ngờ.","en":"This result surprised everyone."},{"zh":"新的制度使工作效率提高了不少。","py":"Xīn de zhìdù shǐ gōngzuò xiàolǜ tígāo le bù shǎo.","vi":"Chế độ mới khiến hiệu suất làm việc tăng lên không ít.","en":"The new system has raised work efficiency considerably."}],"quiz":[{"q":"经理____我下午去银行办点儿事。","options":["使","令","被","让"],"answer":3,"explain":{"vi":"Bảo ai làm việc gì dùng 让/叫, không dùng 使/令.","en":"Telling someone to do something takes 让/叫, not 使/令."}},{"q":"他的表现非常____满意。","options":["令人","被人","把人","对人"],"answer":0,"explain":{"vi":"令人 + tính từ chỉ cảm xúc.","en":"令人 + adjective of feeling."}},{"q":"这次失败____他明白了一个道理。","options":["被","把","使","对"],"answer":2,"explain":{"vi":"使 + người + thay đổi: khiến ai….","en":"使 + person + change: make someone…."}},{"q":"下面哪个句子是正确的？","options":["这个消息令了我们非常吃惊。","这个消息令我们非常吃惊。","这个消息非常吃惊令我们。","我们令这个消息非常吃惊。"],"answer":1,"explain":{"vi":"Nguyên nhân + 令 + người + cảm xúc; sau 令 không có 了.","en":"Cause + 令 + person + feeling; no 了 after 令."}},{"q":"“令人失望”的意思是：","options":["命令别人失望","别人不失望","让人觉得失望","希望别人来"],"answer":2,"explain":{"vi":"令人失望 = khiến người ta thất vọng.","en":"令人失望 = disappointing."}}]}
];
window.CB_HSK5_GRAMMAR_META = {"level":5,"checked":false};
